        public MainWindow()
            : this(new RecipeService(), new AppLogger())
        {
        }

        internal MainWindow(RecipeService recipeService, AppLogger logger)
        {
            if (recipeService == null) throw new ArgumentNullException("recipeService");
            if (logger == null) throw new ArgumentNullException("logger");
            this.recipeService = recipeService;
            this.logger = logger;
            externalResourceService = new ExternalResourceService(recipeService.ResourceDirectory, scriptToolService);
            batchTraceStore = new BatchTraceStore(recipeService.StateDirectory);
            productionRunStoreS135 = new ProductionRunStoreS135(recipeService.StateDirectory);
            productionAlarmStoreS136 = new ProductionAlarmStoreS136(recipeService.StateDirectory);
            stationProtectionS137 = new StationEditingProtectionServiceS137(recipeService.StateDirectory);
            batchTraceStorageSettings = batchTraceStore.LoadSettings();
            InitializeComponent();
            MoveLayerWorkspaceToRightTaskSurface();

            playbackTimer.Interval = TimeSpan.FromMilliseconds(650);
            playbackTimer.Tick += PlaybackTimer_Tick;
            runTimer.Interval = TimeSpan.FromMilliseconds(500);
            runTimer.Tick += RunTimer_Tick;
            InitializeCurrentToolTrialS87();
            InitializeResultTaskAndStabilityS88();
            recipeAutosaveTimer.Interval = TimeSpan.FromMilliseconds(750);
            recipeAutosaveTimer.Tick += RecipeAutosaveTimer_Tick;

            logger.MessageLogged += Logger_MessageLogged;
            tcpService.MessageReceived += TcpService_MessageReceived;
            tcpService.StatusChanged += TcpService_StatusChanged;
            tcpService.ErrorOccurred += TcpService_ErrorOccurred;
            resultStore.Changed += ResultStore_Changed;

            AddHandler(TextBox.TextChangedEvent, new TextChangedEventHandler(RecipeEditor_TextChanged));
            AddHandler(Selector.SelectionChangedEvent, new SelectionChangedEventHandler(RecipeEditor_SelectionChanged));
            AddHandler(ToggleButton.CheckedEvent, new RoutedEventHandler(RecipeEditor_ToggleChanged));
            AddHandler(ToggleButton.UncheckedEvent, new RoutedEventHandler(RecipeEditor_ToggleChanged));

            InitializeVmWorkspace();
            RightTabs.SelectedItem = ModuleResultTab;
            uiReady = true;
        }

        private void MoveLayerWorkspaceToRightTaskSurface()
        {
            Panel currentParent = RoiLayerPanel == null ? null : RoiLayerPanel.Parent as Panel;
            if (currentParent != null && RightLayerTaskHost != null)
            {
                currentParent.Children.Remove(RoiLayerPanel);
                Grid.SetColumn(RoiLayerPanel, 0);
                Grid.SetRow(RoiLayerPanel, 0);
                RoiLayerPanel.Margin = new Thickness(0);
                RoiLayerPanel.BorderThickness = new Thickness(0);
                RoiLayerPanel.HorizontalAlignment = HorizontalAlignment.Stretch;
                RoiLayerPanel.VerticalAlignment = VerticalAlignment.Stretch;
                RoiLayerPanel.Visibility = Visibility.Visible;
                RightLayerTaskHost.Children.Add(RoiLayerPanel);
            }
            if (RoiLayerPanelColumn != null) RoiLayerPanelColumn.Width = new GridLength(0);
            if (ToggleRoiLayerPanelButton != null) ToggleRoiLayerPanelButton.Content = "图层任务";
        }

