        private void RefreshInspector()
        {
            if (FlowToolList == null || InspectorToolTitleText == null)
            {
                return;
            }

            inspectorUpdating = true;
            try
            {
                ImageSourceInspectorPanel.Visibility = Visibility.Collapsed;
                ShapeInspectorPanel.Visibility = Visibility.Collapsed;
                BlobInspectorPanel.Visibility = Visibility.Collapsed;
                GrayInspectorPanel.Visibility = Visibility.Collapsed;
                EdgeInspectorPanel.Visibility = Visibility.Collapsed;
                HDevInspectorPanel.Visibility = Visibility.Collapsed;
                NumericJudgeInspectorPanel.Visibility = Visibility.Collapsed;

                VmToolInstance selected = FlowToolList.SelectedItem as VmToolInstance;
                bool hasSelection = selected != null;
                RightParametersTaskButton.IsEnabled = hasSelection && SupportsDockConfiguration(selected.Kind);
                RightIoTaskButton.IsEnabled = hasSelection && SupportsDockConfiguration(selected.Kind);
                SelectedResultErrorLabel.Visibility = SelectedResultErrorText.Visibility = hasSelection && !string.IsNullOrWhiteSpace(selected.ErrorMessage)
                    ? Visibility.Visible : Visibility.Collapsed;
                InspectorEmptyText.Visibility = hasSelection ? Visibility.Collapsed : Visibility.Visible;
                ToolInstanceNameTextBox.IsEnabled = hasSelection;
                SelectedToolEnabledCheckBox.IsEnabled = hasSelection;

                if (!hasSelection)
                {
                    InspectorToolTitleText.Text = "请选择流程工具";
                    InspectorToolTypeText.Text = "从左侧工具箱添加，或在流程中选择实例";
                    ToolInstanceNameTextBox.Text = string.Empty;
                    SelectedToolEnabledCheckBox.IsChecked = false;
                    SelectedToolStatusText.Text = "--";
                    InspectorInputSummaryText.Text = "--";
                    InspectorOutputSummaryText.Text = "--";
                    InspectorErrorText.Text = "--";
                    SelectedResultToolText.Text = "请选择流程模块；双击配置";
                    SelectedResultStatusText.Text = "--";
                    SelectedResultOutputText.Text = "--";
                    SelectedResultOriginTextS88.Text = "尚无执行结果";
                    SelectedResultErrorText.Text = "--";
                    SelectedRoiResultsDataGrid.ItemsSource = null;
                    RefreshRoiLayerContextResults(null);
                    RefreshPortPanel(null);
                    RefreshRoiBindingEditor();
                    if (centralModuleConfigurationOpenS77 && dockEditingTool != null && flowTools.Contains(dockEditingTool))
                        RefreshDockConfigurationRuntime(dockEditingTool);
                    else if (!centralModuleConfigurationOpenS77) LoadDockConfigurationDraft(null);
                    return;
                }

                RefreshToolConfigurationStatus(selected);
                InspectorToolTitleText.Text = selected.InstanceName;
                InspectorToolTypeText.Text = selected.Category + " / " + selected.DisplayType;
                ToolInstanceNameTextBox.Text = selected.InstanceName;
                SelectedToolEnabledCheckBox.IsChecked = selected.IsEnabled;
                SelectedToolStatusText.Text = selected.ConfigurationStatus + " · " + selected.RunStatus + " · " + selected.ElapsedText;
                InspectorInputSummaryText.Text = selected.InputSummary;
                InspectorOutputSummaryText.Text = selected.OutputSummary;
                InspectorErrorText.Text = string.IsNullOrWhiteSpace(selected.ErrorMessage) ? "--" : selected.ErrorMessage;
                SelectedResultToolText.Text = selected.InstanceName + " · " + selected.DisplayType;
                SelectedResultStatusText.Text = selected.ResultCode + " · " + selected.RunStatus + " · " + selected.ElapsedText;
                SelectedResultOutputText.Text = BuildBriefTaskValuesS88(selected);
                SelectedResultOriginTextS88.Text = BuildResultOriginTextS88(selected);
                SelectedResultErrorText.Text = string.IsNullOrWhiteSpace(selected.ErrorMessage) ? "--" : selected.ErrorMessage;
                SelectedRoiResultsDataGrid.ItemsSource = selected.RoiResults;
                VmToolParameterData selectedParameters = selected.Parameters ?? new VmToolParameterData();
                BlobMinGrayTextBox.Text = selectedParameters.BlobMinGray.ToString("0.###", CultureInfo.InvariantCulture);
                BlobMaxGrayTextBox.Text = selectedParameters.BlobMaxGray.ToString("0.###", CultureInfo.InvariantCulture);
                BlobMinAreaTextBox.Text = selectedParameters.BlobMinArea.ToString("0.###", CultureInfo.InvariantCulture);
                GrayMinTextBox.Text = selectedParameters.GrayMin.ToString("0.###", CultureInfo.InvariantCulture);
                GrayMaxTextBox.Text = selectedParameters.GrayMax.ToString("0.###", CultureInfo.InvariantCulture);
                EdgeThresholdTextBox.Text = selectedParameters.EdgeThreshold.ToString("0.###", CultureInfo.InvariantCulture);
                ImageSourcePathText.Text = BuildImageSourceInspectorTextS114(selected, selectedParameters);
                ImageSourceSerialText.Text = BuildImageSourceInspectorSerialS114(selected, selectedParameters);

                switch (selected.Kind)
                {
                    case VmToolKind.ImageSource:
                        ImageSourceInspectorPanel.Visibility = Visibility.Visible;
                        break;
                    case VmToolKind.ShapeMatch:
                        ShapeInspectorPanel.Visibility = Visibility.Visible;
                        break;
                    case VmToolKind.Blob:
                        BlobInspectorPanel.Visibility = Visibility.Visible;
                        break;
                    case VmToolKind.GrayStat:
                        GrayInspectorPanel.Visibility = Visibility.Visible;
                        break;
                    case VmToolKind.EdgeMeasure:
                        EdgeInspectorPanel.Visibility = Visibility.Visible;
                        break;
                    case VmToolKind.HDevelop:
                        HDevInspectorPanel.Visibility = Visibility.Visible;
                        break;
                    case VmToolKind.NumericJudge:
                        NumericJudgeInspectorPanel.Visibility = Visibility.Visible;
                        RefreshNumericJudgeEditor(selected);
                        break;
                }

                if (centralModuleConfigurationOpenS77 && dockEditingTool != null && flowTools.Contains(dockEditingTool))
                {
                    RefreshDockConfigurationRuntime(dockEditingTool);
                }
                else if (!ReferenceEquals(dockEditingTool, selected))
                {
                    LoadDockConfigurationDraft(selected);
                }
                else
                {
                    RefreshDockConfigurationRuntime(selected);
                }

                RefreshPortPanel(selected);
                RefreshRoiBindingEditor();
                RefreshRoiLayerContextResults(selected);
            }
            finally
            {
                inspectorUpdating = false;
            }
        }

        private void RefreshToolConfigurationStatus(VmToolInstance tool)
        {
            if (!tool.IsEnabled)
            {
                tool.ConfigurationStatus = "已停用";
                tool.ConnectionStatus = "已停用";
                return;
            }

            VmToolParameterData parameters = tool.Parameters ?? new VmToolParameterData();
            string parameterError = parameters.Validate(tool.Kind);
            if (!string.IsNullOrWhiteSpace(parameterError))
            {
                tool.ConfigurationStatus = "参数异常";
                tool.ConnectionStatus = parameterError;
                if (tool.Kind == VmToolKind.ImageSource) tool.ConnectionSummary = "图像来源 → Image / SN / 时间";
                else if (tool.Kind == VmToolKind.TcpClientExchange) tool.ConnectionSummary = "String/Number/ResultCode → TCP 发送/响应";
                else if (tool.Kind == VmToolKind.ModbusTcpExchange) tool.ConnectionSummary = "Modbus TCP 配置异常";
                else if (tool.Kind == VmToolKind.ModbusRtuExchange) tool.ConnectionSummary = "Modbus RTU 串口配置异常";
                else if (tool.Kind == VmToolKind.TextAssembly) tool.ConnectionSummary = "String/Number/ResultCode → Text";
                else if (tool.Kind == VmToolKind.TextParser) tool.ConnectionSummary = "String → Text/Number/状态";
                else if (VmArrayReorderS108.IsTool(tool.Kind)) tool.ConnectionSummary = "数组与索引 → 数组整理";
                else if (tool.Kind == VmToolKind.NumericExpression) tool.ConnectionSummary = "公式变量 → 公式 → Number";
                else if (VmArrayContractS105.IsTool(tool.Kind)) tool.ConnectionSummary = "数组配置 / 来源 → 统计与取值";
                else if (tool.Kind == VmToolKind.NumericCalculation) tool.ConnectionSummary = "NumberA + 可选 NumberB → Number";
                else if (tool.Kind == VmToolKind.ResultLogicAggregation) tool.ConnectionSummary = "ResultCodeA + 可选 ResultCodeB → OK/NG";
                else if (tool.Kind == VmToolKind.CSharpDllScript) tool.ConnectionSummary = "可选类型化输入 + 参数 → C# / DLL → 类型化输出";
                else if (tool.Kind == VmToolKind.GlobalVariableRead) tool.ConnectionSummary = "全局变量 → 强类型值";
                else if (tool.Kind == VmToolKind.GlobalVariableWrite) tool.ConnectionSummary = "强类型值 → 全局变量";
                else if (tool.Kind == VmToolKind.ImageDifference) tool.ConnectionSummary = "ImageA + ImageB → 双图像差分";
                else if (tool.Kind == VmToolKind.DynamicThreshold) tool.ConnectionSummary = "OriginalImage + ReferenceImage → 动态阈值分割";
                else if (tool.Kind == VmToolKind.LocalAdaptiveThreshold) tool.ConnectionSummary = "Image → HALCON 局部自适应阈值 → Region + Number";
                else if (tool.Kind == VmToolKind.ColorInspectionHsv) tool.ConnectionSummary = "RGB Image + ROI/屏蔽 → HSV 颜色区域 / 覆盖比例";
                else if (tool.Kind == VmToolKind.VariationSurfaceInspection) tool.ConnectionSummary = "已对齐 Image + 多良品学习 → 缺陷区域 / 面积 / 比例";
                else if (tool.Kind == VmToolKind.NccTemplateMatch) tool.ConnectionSummary = "灰度 Image + NCC 模板 → 分数 / Point / Pose";
                else if (tool.Kind == VmToolKind.PoseImageAlignment) tool.ConnectionSummary = "Image + 同源 Pose → 参考画布 Image / 有效域";
                else if (tool.Kind == VmToolKind.GrayHistogram) tool.ConnectionSummary = "Image + ROI/屏蔽有效域 → HALCON 灰度分布 → Region + Number";
                else if (tool.Kind == VmToolKind.GrayLineProfile) tool.ConnectionSummary = "Image → HALCON 灰度线剖面 → XLD + Number";
                else if (tool.Kind == VmToolKind.BranchValueSelection) tool.ConnectionSummary = "Boolean → 真/假路径 → " + ToolMetadata.NormalizeBranchValueType((tool.Parameters ?? new VmToolParameterData()).BranchValueType);
                else if (tool.Kind == VmToolKind.SubflowCall) tool.ConnectionSummary = "输入参数 → 子流程调用 → 返回结果";
                else if (tool.Kind == VmToolKind.ImageChannel || tool.Kind == VmToolKind.ImageFilter || tool.Kind == VmToolKind.ImageEnhancement || tool.Kind == VmToolKind.ImageResize || tool.Kind == VmToolKind.ImageMirror || tool.Kind == VmToolKind.ImageRotate || tool.Kind == VmToolKind.ImageAffineTransform || tool.Kind == VmToolKind.ImageProjectiveTransform || tool.Kind == VmToolKind.PolarImageUnwrap || tool.Kind == VmToolKind.RoiImageExtraction || tool.Kind == VmToolKind.ImageThreshold || tool.Kind == VmToolKind.AutomaticThreshold || tool.Kind == VmToolKind.DataCode2DRecognition || tool.Kind == VmToolKind.BarCode1DRecognition || tool.Kind == VmToolKind.CaliperEdgePairMeasurement || tool.Kind == VmToolKind.LinearCaliperArrayMeasurement || tool.Kind == VmToolKind.CircularCaliperCircleFinder || tool.Kind == VmToolKind.RingWallThicknessMeasurement) tool.ConnectionSummary = "Image → " + tool.DisplayType;
                else if (tool.Kind == VmToolKind.RegionSetOperation) tool.ConnectionSummary = "RegionA + RegionB → " + tool.DisplayType;
                else if (tool.Kind == VmToolKind.RegionMorphology || tool.Kind == VmToolKind.RegionFeatureFilter || tool.Kind == VmToolKind.RegionContourMeasurement) tool.ConnectionSummary = "Region → " + tool.DisplayType;
                else if (tool.Kind == VmToolKind.XldContourFilter || tool.Kind == VmToolKind.XldAdjacentContourUnion || tool.Kind == VmToolKind.XldContourSmoothing || tool.Kind == VmToolKind.XldAffineTransform || tool.Kind == VmToolKind.XldProjectiveTransform || tool.Kind == VmToolKind.XldContourCrop || tool.Kind == VmToolKind.XldLengthClassification || tool.Kind == VmToolKind.XldLengthSortSelection || tool.Kind == VmToolKind.XldPointClosureFilter || tool.Kind == VmToolKind.XldAreaDirectionFilter || tool.Kind == VmToolKind.XldBoundingCompactnessFilter || tool.Kind == VmToolKind.XldCircularityConvexityFilter || tool.Kind == VmToolKind.XldEnclosingCircleDiameterMeasurement || tool.Kind == VmToolKind.XldMinimumRectangleDirectionMeasurement || tool.Kind == VmToolKind.XldDirectionConsistencyMeasurement || tool.Kind == VmToolKind.XldContourSegmentation || tool.Kind == VmToolKind.XldLineFitting || tool.Kind == VmToolKind.XldCircleFitting || tool.Kind == VmToolKind.XldEllipseFitting || tool.Kind == VmToolKind.XldRectangleFitting) tool.ConnectionSummary = "XLD → " + tool.DisplayType;
                else if (tool.Kind == VmToolKind.XldLineRelationMeasurement) tool.ConnectionSummary = "LineA + LineB → " + tool.DisplayType;
                else if (tool.Kind == VmToolKind.PointToLineDistanceMeasurement) tool.ConnectionSummary = "Point2D + Line2D → FootPoint / Distance / XLD";
                else if (tool.Kind == VmToolKind.PointToCircleRadialDeviationMeasurement) tool.ConnectionSummary = "Point2D + Circle2D → ClosestPoint / RadialDeviation / XLD";
                else if (tool.Kind == VmToolKind.PointToEllipseDistanceMeasurement) tool.ConnectionSummary = "Point2D + Ellipse2D → ClosestPoint / Distance / Relation / XLD";
                else if (tool.Kind == VmToolKind.LineEllipseIntersectionMeasurement) tool.ConnectionSummary = "Line2D + Ellipse2D → Point2D[] / Relation / ChordLength / XLD";
                else if (tool.Kind == VmToolKind.LineCircleIntersectionMeasurement) tool.ConnectionSummary = "Line2D + Circle2D → Point2D[] / Relation / ChordLength / XLD";
                else if (tool.Kind == VmToolKind.CircleCircleIntersectionMeasurement) tool.ConnectionSummary = "Circle2D + Circle2D → Point2D[] / Relation / CenterDistance / XLD";
                else if (tool.Kind == VmToolKind.PointPairLineConstructionMeasurement) tool.ConnectionSummary = "Point2D + Point2D → Line2D / MidPoint / Distance / XLD";
                else if (tool.Kind == VmToolKind.TypedLineLineRelationMeasurement) tool.ConnectionSummary = "Line2D + Line2D → IntersectionPoint / Angle / ParallelDistance / XLD";
                else if (tool.Kind == VmToolKind.TypedPointSetLineFittingMeasurement) tool.ConnectionSummary = "Point2D[] → Line2D / Residual / XLD";
                else if (tool.Kind == VmToolKind.TypedPointSetCircleFittingMeasurement) tool.ConnectionSummary = "Point2D[] → Circle2D / Radius / Residual / XLD";
                else if (tool.Kind == VmToolKind.TypedPointSetEllipseFittingMeasurement) tool.ConnectionSummary = "Point2D[] → Ellipse2D / Axis / Residual / XLD";
                else tool.ConnectionSummary = "系统.Image + " + GetRoiBindingSummary(tool);
                return;
            }

            string inputBindingError = tool.InputBindings
                .Select(binding => GetInputBindingConfigurationError(tool, binding))
                .FirstOrDefault(error => !string.IsNullOrWhiteSpace(error));
            if (!string.IsNullOrWhiteSpace(inputBindingError))
            {
                tool.ConfigurationStatus = "输入异常";
                tool.ConnectionStatus = inputBindingError;
                tool.ConnectionSummary = tool.Kind == VmToolKind.TypedLineLineRelationMeasurement
                    ? "Line2D + Line2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.TypedPointSetLineFittingMeasurement
                    ? "Point2D[] ← 输入连接异常"
                    : tool.Kind == VmToolKind.TypedPointSetCircleFittingMeasurement
                    ? "Point2D[] ← 输入连接异常"
                    : tool.Kind == VmToolKind.TypedPointSetEllipseFittingMeasurement
                    ? "Point2D[] ← 输入连接异常"
                    : tool.Kind == VmToolKind.PointPairLineConstructionMeasurement
                    ? "Point2D + Point2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.CircleCircleIntersectionMeasurement
                    ? "Circle2D + Circle2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.LineCircleIntersectionMeasurement
                    ? "Line2D + Circle2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.PointToCircleRadialDeviationMeasurement
                    ? "Point2D + Circle2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.PointToEllipseDistanceMeasurement
                    ? "Point2D + Ellipse2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.LineEllipseIntersectionMeasurement
                    ? "Line2D + Ellipse2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.DataCode2DRecognition
                    ? "Image ← 输入连接异常"
                    : tool.Kind == VmToolKind.BarCode1DRecognition
                    ? "Image ← 输入连接异常"
                    : tool.Kind == VmToolKind.PointToLineDistanceMeasurement
                    ? "Point2D + Line2D ← 输入连接异常"
                    : tool.Kind == VmToolKind.RegionSetOperation
                    ? "RegionA + RegionB ← 输入连接异常"
                    : (tool.Kind == VmToolKind.XldLineRelationMeasurement
                        ? "LineA + LineB ← 输入连接异常"
                        : (tool.Kind == VmToolKind.XldContourFilter || tool.Kind == VmToolKind.XldAdjacentContourUnion || tool.Kind == VmToolKind.XldContourSmoothing || tool.Kind == VmToolKind.XldAffineTransform || tool.Kind == VmToolKind.XldProjectiveTransform || tool.Kind == VmToolKind.XldContourCrop || tool.Kind == VmToolKind.XldLengthClassification || tool.Kind == VmToolKind.XldLengthSortSelection || tool.Kind == VmToolKind.XldPointClosureFilter || tool.Kind == VmToolKind.XldAreaDirectionFilter || tool.Kind == VmToolKind.XldBoundingCompactnessFilter || tool.Kind == VmToolKind.XldCircularityConvexityFilter || tool.Kind == VmToolKind.XldEnclosingCircleDiameterMeasurement || tool.Kind == VmToolKind.XldMinimumRectangleDirectionMeasurement || tool.Kind == VmToolKind.XldDirectionConsistencyMeasurement || tool.Kind == VmToolKind.XldContourSegmentation || tool.Kind == VmToolKind.XldLineFitting || tool.Kind == VmToolKind.XldCircleFitting || tool.Kind == VmToolKind.XldEllipseFitting || tool.Kind == VmToolKind.XldRectangleFitting ? "XLD ← 输入连接异常" : GetRoiInputSummary(tool)));
                return;
            }

            string regionSetInputError = GetRegionSetInputConfigurationError(tool);
            if (!string.IsNullOrWhiteSpace(regionSetInputError))
            {
                tool.ConfigurationStatus = "输入异常";
                tool.ConnectionStatus = regionSetInputError;
                tool.ConnectionSummary = "RegionA + RegionB ← 需要两路不同的前序 Region";
                return;
            }

            string dynamicThresholdInputError = GetDynamicThresholdInputConfigurationError(tool);
            if (!string.IsNullOrWhiteSpace(dynamicThresholdInputError))
            {
                tool.ConfigurationStatus = "输入异常";
                tool.ConnectionStatus = dynamicThresholdInputError;
                tool.ConnectionSummary = "OriginalImage + ReferenceImage ← 需要两路不同的前序单通道 Image";
                return;
            }

            string imageDifferenceInputError = GetImageDifferenceInputConfigurationError(tool);
            if (!string.IsNullOrWhiteSpace(imageDifferenceInputError))
            {
                tool.ConfigurationStatus = "输入异常";
                tool.ConnectionStatus = imageDifferenceInputError;
                tool.ConnectionSummary = "ImageA + ImageB ← 需要两路不同的前序同规格 Image";
                return;
            }

            if (VmArrayContractS105.IsTool(tool.Kind)) { RefreshArrayConnectionStatusS105(tool); return; }
            if (tool.Kind == VmToolKind.NumericExpression) { RefreshExpressionConnectionStatusS106(tool); return; }
            if (VmStructuredDataS110.IsTool(tool.Kind)) { RefreshJsonConnectionS110(tool); return; }
            if (VmArrayReorderS108.IsTool(tool.Kind)) { RefreshArrayReorderConnectionS108(tool); return; }
            string lineRelationInputError = GetXldLineRelationInputConfigurationError(tool);
            if (!string.IsNullOrWhiteSpace(lineRelationInputError))
            {
                tool.ConfigurationStatus = "输入异常";
                tool.ConnectionStatus = lineRelationInputError;
                tool.ConnectionSummary = "LineA + LineB ← 需要两路不同的前序 XLD";
                return;
            }

            switch (tool.Kind)
            {
                case VmToolKind.ImageSource:
                    tool.ConfigurationStatus = "就绪";
                    tool.ConnectionStatus = BuildImageSourceConnectionStatusS114(tool, parameters);
                    tool.ConnectionSummary = BuildImageSourceConnectionSummaryS114(parameters);
                    break;
                case VmToolKind.NumericJudge:
                    RefreshNumericJudgeConnectionStatus(tool);
                    break;
                case VmToolKind.TcpClientExchange:
                {
                    List<VmToolInputBindingData> tcpBindings = tool.InputBindings.ToList();
                    bool waiting = false;
                    foreach (VmToolInputBindingData binding in tcpBindings)
                    {
                        VmToolInstance inputSource = GetInputSourceTool(binding);
                        object raw;
                        if (inputSource == null || !inputSource.TryGetOutputValue(binding.SourcePortName, out raw) || raw == null)
                        {
                            waiting = true;
                            break;
                        }
                    }
                    tool.ConfigurationStatus = waiting ? "等待上游" : "就绪";
                    tool.ConnectionStatus = tcpBindings.Count == 0
                        ? "模板常量 · 可运行"
                        : (waiting ? "变量已订阅 · 等待上游" : "变量已订阅 · 有值");
                    if (parameters.CommunicationSimulationS121 && !waiting) tool.ConnectionStatus = "离线样本 · 不连接网络";
                    tool.ConnectionSummary = (parameters.CommunicationSimulationS121 ? "离线模拟 · " : "真实设备 · ") +
                        BuildTcpClientInputSummary(tool) + " → " + parameters.TcpClientHost + ":" + parameters.TcpClientPort.ToString(CultureInfo.InvariantCulture);
                    break;
                }
                case VmToolKind.ModbusTcpExchange:
                    RefreshModbusConnectionStatusS118(tool, parameters);
                    break;
                case VmToolKind.ModbusRtuExchange:
                    RefreshRtuConnectionStatusS119(tool, parameters);
                    break;
                case VmToolKind.TextAssembly:
                {
                    List<VmToolInputBindingData> textBindings = tool.InputBindings.ToList();
                    bool waiting = textBindings.Any(binding =>
                    {
                        VmToolInstance inputSource = GetInputSourceTool(binding);
                        object raw;
                        return inputSource == null || !inputSource.TryGetOutputValue(binding.SourcePortName, out raw) || raw == null;
                    });
                    tool.ConfigurationStatus = waiting ? "等待上游" : "就绪";
                    tool.ConnectionStatus = textBindings.Count == 0
                        ? "模板常量 · 可运行"
                        : (waiting ? "变量已订阅 · 等待上游" : "变量已订阅 · 有值");
                    tool.ConnectionSummary = BuildTextAssemblyInputSummary(tool) + " → Text";
                    break;
                }
                case VmToolKind.TextParser:
                {
                    VmToolInputBindingData binding = tool.GetInputBinding("String");
                    VmToolInstance source = GetInputSourceTool(binding);
                    object raw;
                    bool ready = source != null && binding != null && source.TryGetOutputValue(binding.SourcePortName, out raw) && raw != null;
                    tool.ConfigurationStatus = binding == null ? "待连接 String" : (ready ? "就绪" : "等待上游");
                    tool.ConnectionStatus = binding == null ? "String 未连接" : (ready ? "String 已连接 · 有值" : "String 已连接 · 等待上游");
                    tool.ConnectionSummary = source == null || binding == null
                        ? "String ← 请选择上游文本"
                        : source.InstanceName + "." + binding.SourcePortName + " → Text/Number";
                    break;
                }
                case VmToolKind.NumericCalculation:
                {
                    VmToolInputBindingData bindingA = tool.GetInputBinding("NumberA");
                    VmToolInputBindingData bindingB = tool.GetInputBinding("NumberB");
                    VmToolInstance sourceA = GetInputSourceTool(bindingA);
                    VmToolInstance sourceB = GetInputSourceTool(bindingB);
                    object rawA;
                    object rawB;
                    bool readyA = sourceA != null && bindingA != null && sourceA.TryGetOutputValue(bindingA.SourcePortName, out rawA) && rawA != null;
                    bool needsB = VmNumericCalculationOperation.RequiresSecondOperand(parameters.NumericCalculationOperation);
                    bool readyB = !needsB || (sourceB != null && bindingB != null && sourceB.TryGetOutputValue(bindingB.SourcePortName, out rawB) && rawB != null);
                    tool.ConfigurationStatus = bindingA == null || (needsB && bindingB == null) ? "待连接数值" : (readyA && readyB ? "就绪" : "等待上游");
                    tool.ConnectionStatus = bindingA == null
                        ? "NumberA 未连接"
                        : (needsB && bindingB == null ? "当前双目运算需要 NumberB" : (readyA && readyB ? "数值输入已连接 · 有值" : "数值输入已连接 · 等待上游"));
                    tool.ConnectionSummary = BuildNumericCalculationInputSummary(tool) + " → Number";
                    break;
                }
                case VmToolKind.PositionCorrection2D:
                {
                    string[] requiredPorts = { "CurrentRow", "CurrentColumn", "CurrentAngle" };
                    bool connected = requiredPorts.All(name => tool.GetInputBinding(name) != null);
                    bool ready = connected && requiredPorts.All(name =>
                    {
                        VmToolInputBindingData binding = tool.GetInputBinding(name);
                        VmToolInstance source = GetInputSourceTool(binding);
                        object raw;
                        return source != null && source.TryGetOutputValue(binding.SourcePortName, out raw) && raw != null;
                    });
                    tool.ConfigurationStatus = !connected ? "待连接位姿" : (ready ? "就绪" : "等待上游");
                    tool.ConnectionStatus = !connected ? "CurrentRow / CurrentColumn / CurrentAngle 必须全部连接" : (ready ? "3 路位姿已连接 · 有值" : "3 路位姿已连接 · 等待上游");
                    tool.ConnectionSummary = BuildPositionCorrectionInputSummary(tool) + " → HomMat2D / ΔRow / ΔColumn / ΔAngle";
                    break;
                }
                case VmToolKind.PlanarCalibration2D:
                {
                    bool imageReady = HasToolInputImage(tool, "Image", false);
                    int sampleCount = tool.Parameters == null || tool.Parameters.PlanarCalibrationSamplesS124 == null ? 0 : tool.Parameters.PlanarCalibrationSamplesS124.Count;
                    tool.ConfigurationStatus = sampleCount < 3 ? "待采样标定点" : tool.GetInputBinding("Image") == null ? "待连接图像" : imageReady ? "就绪" : "等待图像";
                    tool.ConnectionStatus = "Image " + (imageReady ? "有值" : "待运行") + " · 已采样 " + sampleCount.ToString(CultureInfo.InvariantCulture) + " 点";
                    tool.ConnectionSummary = BuildPlanarCalibrationInputSummaryS124(tool) + " → World2D / 世界距离 / 残差";
                    break;
                }
                case VmToolKind.WorldPointPairMeasurement:
                {
                    bool connected = tool.GetInputBinding("PointA") != null && tool.GetInputBinding("PointB") != null;
                    tool.ConfigurationStatus = connected ? "就绪" : "待连接世界点";
                    tool.ConnectionStatus = connected ? "两路 World2D 已连接 · 运行时检查标定和单位" : "请在输入页连接两路 World2D";
                    tool.ConnectionSummary = BuildWorldPairInputSummaryS125(tool) + " → 世界距离 / 方向 / 中点";
                    break;
                }
                case VmToolKind.CameraDistortionCorrection:
                {
                    bool connected = tool.GetInputBinding("Image") != null;
                    bool hasCamera = tool.Parameters != null && tool.Parameters.CameraIntrinsicsS126 != null;
                    bool imageReady = connected && HasToolInputImage(tool, "Image", false);
                    tool.ConfigurationStatus = !connected ? "待连接图像" : !hasCamera ? "待导入内参" : imageReady ? "就绪" : "等待图像";
                    tool.ConnectionStatus = (connected ? (imageReady ? "Image 有值" : "Image 待运行") : "Image 未连接") + " · " + (hasCamera ? "内参已保存" : "内参未提供");
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " → 独立畸变校正 Image";
                    break;
                }
                case VmToolKind.ColorInspectionHsv:
                {
                    bool connected = tool.GetInputBinding("Image") != null;
                    bool ready = connected && HasToolInputImage(tool, "Image", false);
                    tool.ConfigurationStatus = !connected ? "待连接 RGB 图像" : ready ? "就绪" : "等待图像";
                    tool.ConnectionStatus = connected ? (ready ? "RGB 待运行时检查通道/幅值" : "Image 待上游运行") : "请在输入页选择彩色 Image";
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " → 颜色区域 / 覆盖比例";
                    break;
                }
                case VmToolKind.VariationSurfaceInspection:
                {
                    var p = tool.Parameters.VariationInspectionS130 ?? new VmVariationParametersS130();
                    bool connected = tool.GetInputBinding("Image") != null;
                    bool model = p.HasModelVersion() && File.Exists(p.ModelPath) && File.Exists(p.CoveragePath);
                    tool.ConfigurationStatus = !connected ? "待连接单通道图像" : !model ? "待学习良品模型" : "模型已配置";
                    tool.ConnectionStatus = connected ? (HasToolInputImage(tool, "Image", false) ? "Image 有值" : "Image 待上游运行") : "Image 未连接";
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " → 良品变化缺陷 / 面积";
                    break;
                }
                case VmToolKind.NccTemplateMatch:
                {
                    var p = tool.Parameters.NccMatchingS131 ?? new VmNccParametersS131();
                    bool connected = tool.GetInputBinding("Image") != null;
                    bool model = p.HasModel && File.Exists(p.ModelPath);
                    tool.ConfigurationStatus = !connected ? "待连接灰度图像" : !model ? "待制作 NCC 模板" : "模板已配置";
                    tool.ConnectionStatus = connected ? (HasToolInputImage(tool, "Image", false) ? "Image 有值" : "Image 待上游运行") : "Image 未连接";
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " → NCC 分数 / 位姿";
                    break;
                }
                case VmToolKind.PoseImageAlignment:
                {
                    var p = tool.Parameters.PoseImageAlignmentS132 ?? new VmPoseImageAlignmentParametersS132();
                    bool connected = tool.GetInputBinding("Image") != null && tool.GetInputBinding("Pose") != null;
                    tool.ConfigurationStatus = !connected ? "待连接 Image / Pose" : !p.HasReference ? "待保存固定参考" : "参考已配置";
                    tool.ConnectionStatus = connected ? "Image / Pose 已连接 · 运行时检查同图像链" : "需要图像和定位位姿";
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " → 固定参考对齐 Image";
                    break;
                }
                case VmToolKind.ImageEdgeLineFindingS143:
                {
                    bool ready = CanPreviewEdgeLineS143(tool);
                    tool.ConfigurationStatus = tool.GetInputBinding("Image") == null ? "待连接明确图像" : ready ? "可画搜索带" : "等待上游图像";
                    tool.ConnectionStatus = ready ? "正式 Image 有值 · 运行时检查真实有效域" : "图像来源缺失/未运行，不回退旧图";
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " → 像素直线 / 真实采点";
                    break;
                }
                case VmToolKind.PointSetGeometryStatistics:
                    RefreshPointSetGeometryConnectionStatusS65(tool);
                    break;
                case VmToolKind.PointToLineDistanceMeasurement:
                    RefreshPointToLineConnectionStatusS66(tool);
                    break;
                case VmToolKind.PointToCircleRadialDeviationMeasurement:
                    RefreshPointToCircleConnectionStatusS67(tool);
                    break;
                case VmToolKind.PointToEllipseDistanceMeasurement:
                    RefreshPointToEllipseConnectionStatusS75(tool);
                    break;
                case VmToolKind.LineEllipseIntersectionMeasurement:
                    RefreshLineEllipseIntersectionConnectionStatusS76(tool);
                    break;
                case VmToolKind.DataCode2DRecognition:
                    RefreshDataCodeConnectionStatusS77(tool);
                    break;
                case VmToolKind.BarCode1DRecognition:
                    RefreshBarCodeConnectionStatusS80(tool);
                    break;
                case VmToolKind.OcrRecognition:
                    RefreshOcrConnectionStatusS81(tool);
                    break;
                case VmToolKind.LineCircleIntersectionMeasurement:
                    RefreshLineCircleConnectionStatusS68(tool);
                    break;
                case VmToolKind.CircleCircleIntersectionMeasurement:
                    RefreshCircleCircleConnectionStatusS69(tool);
                    break;
                case VmToolKind.PointPairLineConstructionMeasurement:
                    RefreshPointPairLineConnectionStatusS70(tool);
                    break;
                case VmToolKind.TypedLineLineRelationMeasurement:
                    RefreshTypedLineLineConnectionStatusS71(tool);
                    break;
                case VmToolKind.TypedPointSetLineFittingMeasurement:
                    RefreshTypedPointSetLineFitConnectionStatusS72(tool);
                    break;
                case VmToolKind.TypedPointSetCircleFittingMeasurement:
                    RefreshTypedPointSetCircleFitConnectionStatusS73(tool);
                    break;
                case VmToolKind.TypedPointSetEllipseFittingMeasurement:
                    RefreshTypedPointSetEllipseFitConnectionStatusS74(tool);
                    break;
                case VmToolKind.ResultLogicAggregation:
                {
                    VmToolInputBindingData bindingA = tool.GetInputBinding("ResultCodeA");
                    VmToolInputBindingData bindingB = tool.GetInputBinding("ResultCodeB");
                    VmToolInstance sourceA = GetInputSourceTool(bindingA);
                    VmToolInstance sourceB = GetInputSourceTool(bindingB);
                    object rawA;
                    object rawB;
                    bool readyA = sourceA != null && bindingA != null && sourceA.TryGetOutputValue(bindingA.SourcePortName, out rawA) && rawA != null;
                    bool needsB = VmResultLogicOperation.RequiresSecondInput(parameters.ResultLogicOperation);
                    bool readyB = !needsB || (sourceB != null && bindingB != null && sourceB.TryGetOutputValue(bindingB.SourcePortName, out rawB) && rawB != null);
                    tool.ConfigurationStatus = bindingA == null || (needsB && bindingB == null) ? "待连接结果码" : (readyA && readyB ? "就绪" : "等待上游");
                    tool.ConnectionStatus = bindingA == null
                        ? "ResultCodeA 未连接"
                        : (needsB && bindingB == null ? "当前双目逻辑需要 ResultCodeB" : (readyA && readyB ? "结果码输入已连接 · 有值" : "结果码输入已连接 · 等待上游"));
                    tool.ConnectionSummary = BuildResultLogicInputSummary(tool) + " → OK/NG";
                    break;
                }
                case VmToolKind.CSharpDllScript:
                {
                    IList<VmPortDefinition> ports = ToolMetadata.GetInstanceInputPorts(tool);
                    List<string> waiting = new List<string>();
                    List<string> missingRequired = new List<string>();
                    int connected = 0;
                    foreach (VmPortDefinition port in ports)
                    {
                        VmToolInputBindingData binding = tool.GetInputBinding(port.PortName);
                        if (binding == null) continue;
                        connected++;
                        VmToolInstance source = GetInputSourceTool(binding);
                        object raw;
                        if (source == null || !source.TryGetOutputValue(binding.SourcePortName, out raw) || raw == null) waiting.Add(port.PortName);
                    }
                    foreach (VmScriptInterfaceMemberData member in parameters.ScriptInterfaceMembers.Where(item => item.Direction == VmScriptMemberDirection.Input && item.IsRequired))
                    {
                        if (tool.GetInputBinding(member.PortName) == null) missingRequired.Add(member.Name);
                    }
                    tool.ConfigurationStatus = missingRequired.Count > 0 ? "待连接脚本输入" : (waiting.Count == 0 ? "就绪" : "等待上游");
                    tool.ConnectionStatus = missingRequired.Count > 0
                        ? "必需输入未连接：" + string.Join("、", missingRequired)
                        : (waiting.Count == 0
                        ? (connected == 0 ? "无订阅 · 使用受控参数" : connected.ToString(CultureInfo.InvariantCulture) + " 路输入已连接 · 有值")
                        : "等待输入：" + string.Join("、", waiting));
                    tool.ConnectionSummary = BuildScriptInputSummary(tool) + " → Number/Text/OK-NG";
                    break;
                }
                case VmToolKind.GlobalVariableRead:
                case VmToolKind.GlobalVariableWrite:
                {
                    VmGlobalVariableData variable = parameters == null ? null : globalVariables.FirstOrDefault(item => string.Equals(item.VariableId, parameters.GlobalVariableId, StringComparison.OrdinalIgnoreCase));
                    if (variable == null)
                    {
                        tool.ConfigurationStatus = "待选择变量";
                        tool.ConnectionStatus = "变量无效或不存在";
                        tool.ConnectionSummary = tool.Kind == VmToolKind.GlobalVariableRead ? "全局变量 → 强类型值" : "强类型值 → 全局变量";
                    }
                    else if (tool.Kind == VmToolKind.GlobalVariableRead)
                    {
                        tool.ConfigurationStatus = "就绪";
                        tool.ConnectionStatus = variable.TypeDisplayText + " · 当前有值";
                        tool.ConnectionSummary = BuildGlobalVariableToolInputSummary(tool) + " → " + VmGlobalVariableType.GetWritePortName(variable.ValueType);
                    }
                    else
                    {
                        string activePort = VmGlobalVariableType.GetWritePortName(variable.ValueType);
                        VmToolInputBindingData binding = tool.GetInputBinding(activePort);
                        VmToolInstance source = GetInputSourceTool(binding);
                        object raw;
                        bool ready = source != null && binding != null && source.TryGetOutputValue(binding.SourcePortName, out raw) && raw != null;
                        bool incompatible = tool.InputBindings.Any(item => item.TargetPortName != "$RunCondition" && !string.Equals(item.TargetPortName, activePort, StringComparison.OrdinalIgnoreCase));
                        tool.ConfigurationStatus = incompatible ? "类型冲突" : (binding == null ? "待连接 " + activePort : (ready ? "就绪" : "等待上游"));
                        tool.ConnectionStatus = incompatible ? "存在非目标类型订阅" : (binding == null ? activePort + " 未连接" : (ready ? activePort + " 已连接 · 有值" : activePort + " 已连接 · 等待上游"));
                        tool.ConnectionSummary = BuildGlobalVariableToolInputSummary(tool) + " → " + variable.Name;
                    }
                    break;
                }
                case VmToolKind.RegionMorphology:
                case VmToolKind.RegionFeatureFilter:
                case VmToolKind.RegionContourMeasurement:
                case VmToolKind.ConnectedObjectAnalysisS144:
                {
                    VmToolInputBindingData requiredRegionBinding = tool.GetInputBinding("Region");
                    VmToolInstance requiredRegionSource = GetInputSourceTool(requiredRegionBinding);
                    object requiredRegionRaw;
                    VmRegionSnapshot requiredRegionSnapshot = requiredRegionSource != null && requiredRegionBinding != null && requiredRegionSource.TryGetOutputValue(requiredRegionBinding.SourcePortName, out requiredRegionRaw)
                        ? requiredRegionRaw as VmRegionSnapshot
                        : null;
                    bool hasRegion = requiredRegionBinding != null && requiredRegionSource != null &&
                                     (string.Equals(requiredRegionSource.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) ||
                                      (tool.Kind == VmToolKind.ConnectedObjectAnalysisS144 && requiredRegionSource.ResultCode == "NG" && string.IsNullOrWhiteSpace(requiredRegionSource.ErrorMessage))) &&
                                     requiredRegionSnapshot != null && !requiredRegionSnapshot.IsDisposed;
                    tool.ConfigurationStatus = requiredRegionBinding == null ? "待连接 Region" : (hasRegion ? "就绪" : "等待上游");
                    tool.ConnectionStatus = requiredRegionBinding == null
                        ? "Region 未连接"
                        : (hasRegion ? "Region 已连接 · 有值" : "Region 已连接 · 等待上游 OK");
                    if (tool.Kind == VmToolKind.ConnectedObjectAnalysisS144 && requiredRegionBinding != null && !hasRegion)
                        tool.ConnectionStatus = "Region已连接 · 等待本次有效区域（业务NG可分析真实空域）";
                    tool.ConnectionSummary = requiredRegionSource == null || requiredRegionBinding == null
                        ? "Region ← 请选择上游区域"
                        : requiredRegionSource.InstanceName + "." + requiredRegionBinding.SourcePortName + " → Region";
                    break;
                }
                case VmToolKind.XldContourFilter:
                case VmToolKind.XldAdjacentContourUnion:
                case VmToolKind.XldContourSmoothing:
                case VmToolKind.XldAffineTransform:
                case VmToolKind.XldProjectiveTransform:
                case VmToolKind.XldContourCrop:
                case VmToolKind.XldLengthClassification:
                case VmToolKind.XldContourSegmentation:
                case VmToolKind.XldLineFitting:
                case VmToolKind.XldCircleFitting:
                case VmToolKind.XldEllipseFitting:
                case VmToolKind.XldRectangleFitting:
                {
                    VmToolInputBindingData xldBinding = tool.GetInputBinding("XLD");
                    VmToolInstance xldSource = GetInputSourceTool(xldBinding);
                    object xldRaw;
                    VmXldSnapshot xldSnapshot = xldSource != null && xldBinding != null && xldSource.TryGetOutputValue(xldBinding.SourcePortName, out xldRaw)
                        ? xldRaw as VmXldSnapshot
                        : null;
                    bool hasXld = xldBinding != null && xldSource != null &&
                                  string.Equals(xldSource.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) &&
                                  xldSnapshot != null && !xldSnapshot.IsDisposed;
                    tool.ConfigurationStatus = xldBinding == null ? "待连接 XLD" : (hasXld ? "就绪" : "等待上游");
                    tool.ConnectionStatus = xldBinding == null
                        ? "XLD 未连接"
                        : (hasXld ? "XLD 已连接 · 有值" : "XLD 已连接 · 等待上游 OK");
                    tool.ConnectionSummary = xldSource == null || xldBinding == null
                        ? "XLD ← 请选择上游轮廓"
                        : xldSource.InstanceName + "." + xldBinding.SourcePortName + " → XLD";
                    break;
                }
                case VmToolKind.XldLineRelationMeasurement:
                {
                    VmToolInputBindingData lineA = tool.GetInputBinding("LineA");
                    VmToolInputBindingData lineB = tool.GetInputBinding("LineB");
                    VmToolInstance sourceA = GetInputSourceTool(lineA);
                    VmToolInstance sourceB = GetInputSourceTool(lineB);
                    object rawA;
                    object rawB;
                    VmXldSnapshot snapshotA = sourceA != null && lineA != null && sourceA.TryGetOutputValue(lineA.SourcePortName, out rawA) ? rawA as VmXldSnapshot : null;
                    VmXldSnapshot snapshotB = sourceB != null && lineB != null && sourceB.TryGetOutputValue(lineB.SourcePortName, out rawB) ? rawB as VmXldSnapshot : null;
                    bool readyA = sourceA != null && string.Equals(sourceA.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) && snapshotA != null && !snapshotA.IsDisposed;
                    bool readyB = sourceB != null && string.Equals(sourceB.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) && snapshotB != null && !snapshotB.IsDisposed;
                    bool ready = readyA && readyB;
                    tool.ConfigurationStatus = ready ? "就绪" : "等待上游";
                    tool.ConnectionStatus = ready ? "2 路 XLD 已连接 · 有值" : "2 路 XLD 已连接 · 等待上游 OK";
                    tool.ConnectionSummary = sourceA.InstanceName + "." + lineA.SourcePortName + " + " + sourceB.InstanceName + "." + lineB.SourcePortName + " → 直线关系";
                    break;
                }
                case VmToolKind.RegionSetOperation:
                {
                    VmToolInputBindingData regionA = tool.GetInputBinding("RegionA");
                    VmToolInputBindingData regionB = tool.GetInputBinding("RegionB");
                    VmToolInstance sourceA = GetInputSourceTool(regionA);
                    VmToolInstance sourceB = GetInputSourceTool(regionB);
                    object rawA;
                    object rawB;
                    VmRegionSnapshot snapshotA = sourceA != null && regionA != null && sourceA.TryGetOutputValue(regionA.SourcePortName, out rawA) ? rawA as VmRegionSnapshot : null;
                    VmRegionSnapshot snapshotB = sourceB != null && regionB != null && sourceB.TryGetOutputValue(regionB.SourcePortName, out rawB) ? rawB as VmRegionSnapshot : null;
                    bool readyA = sourceA != null && string.Equals(sourceA.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) && snapshotA != null && !snapshotA.IsDisposed;
                    bool readyB = sourceB != null && string.Equals(sourceB.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) && snapshotB != null && !snapshotB.IsDisposed;
                    bool ready = readyA && readyB;
                    tool.ConfigurationStatus = ready ? "就绪" : "等待上游";
                    tool.ConnectionStatus = ready
                        ? "2 路 Region 已连接 · 有值"
                        : "2 路 Region 已连接 · 等待上游 OK";
                    tool.ConnectionSummary = sourceA.InstanceName + "." + regionA.SourcePortName + " + " + sourceB.InstanceName + "." + regionB.SourcePortName + " → Region";
                    break;
                }
                case VmToolKind.DynamicThreshold:
                {
                    VmToolInputBindingData originalBinding = tool.GetInputBinding("OriginalImage");
                    VmToolInputBindingData referenceBinding = tool.GetInputBinding("ReferenceImage");
                    VmToolInstance originalSource = GetInputSourceTool(originalBinding);
                    VmToolInstance referenceSource = GetInputSourceTool(referenceBinding);
                    bool originalReady = HasToolInputImage(tool, "OriginalImage", false);
                    bool referenceReady = HasToolInputImage(tool, "ReferenceImage", false);
                    bool ready = originalReady && referenceReady;
                    tool.ConfigurationStatus = ready ? "就绪" : "等待上游";
                    tool.ConnectionStatus = ready ? "2 路单通道 Image 已连接 · 有值" : "2 路 Image 已连接 · 等待上游 OK";
                    tool.ConnectionSummary = originalSource.InstanceName + "." + originalBinding.SourcePortName + " + " + referenceSource.InstanceName + "." + referenceBinding.SourcePortName + " → Region";
                    break;
                }
                case VmToolKind.ImageDifference:
                {
                    VmToolInputBindingData imageABinding = tool.GetInputBinding("ImageA");
                    VmToolInputBindingData imageBBinding = tool.GetInputBinding("ImageB");
                    VmToolInstance imageASource = GetInputSourceTool(imageABinding);
                    VmToolInstance imageBSource = GetInputSourceTool(imageBBinding);
                    bool imageAReady = HasToolInputImage(tool, "ImageA", false);
                    bool imageBReady = HasToolInputImage(tool, "ImageB", false);
                    bool ready = imageAReady && imageBReady;
                    tool.ConfigurationStatus = ready ? "就绪" : "等待上游";
                    tool.ConnectionStatus = ready ? "2 路 Image 已连接 · 有值" : "2 路 Image 已连接 · 等待上游 OK";
                    tool.ConnectionSummary = imageASource.InstanceName + "." + imageABinding.SourcePortName + " + " + imageBSource.InstanceName + "." + imageBBinding.SourcePortName + " → Image";
                    break;
                }
                case VmToolKind.RoiImageExtraction:
                {
                    bool hasImage = HasToolInputImage(tool);
                    VmToolInputBindingData roiBinding = tool.GetInputBinding("ROI");
                    VmToolInstance roiSource = GetInputSourceTool(roiBinding);
                    object roiRaw;
                    VmRegionSnapshot roiSnapshot = roiSource != null && roiBinding != null && roiSource.TryGetOutputValue(roiBinding.SourcePortName, out roiRaw)
                        ? roiRaw as VmRegionSnapshot
                        : null;
                    bool hasConnectedRegion = roiBinding != null && roiSource != null &&
                                              string.Equals(roiSource.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) &&
                                              roiSnapshot != null && !roiSnapshot.IsDisposed;
                    bool hasBoundRoi = GetBoundDetectionRoiLayers(tool).Count > 0;
                    bool hasRoi = roiBinding == null ? hasBoundRoi : hasConnectedRegion;
                    tool.ConfigurationStatus = !hasImage ? "等待图像" : (!hasRoi ? (roiBinding == null ? "待绑定 ROI" : "等待上游 Region") : "就绪");
                    tool.ConnectionStatus = !hasImage
                        ? "Image 等待上游"
                        : (hasRoi ? (roiBinding == null ? "本地 ROI 已绑定 · 就绪" : "Region 已连接 · 有值") : (roiBinding == null ? "ROI 未绑定" : "Region 已连接 · 等待上游 OK"));
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " + " + GetRoiInputSummary(tool) + " → Image + Offset";
                    break;
                }
                case VmToolKind.ShapeMatch:
                    tool.ConfigurationStatus = !HasShapeModelResource(tool)
                        ? "待配置模板"
                        : (!HasToolInputImage(tool) ? "等待输入图像" : "就绪");
                    tool.ConnectionStatus = tool.ConfigurationStatus == "就绪" ? "输入已就绪" : tool.ConfigurationStatus;
                    tool.ConnectionSummary = GetImageInputSummary(tool) + " + " + (GetBoundDetectionRoiLayers(tool).Count == 0 && GetRoiSourceBindingS86(tool) == null ? "全图搜索" : GetRoiBindingSummary(tool)) + " + 模块模板";
                    break;
                case VmToolKind.HDevelop:
                    tool.ConfigurationStatus = string.IsNullOrWhiteSpace(HDevPathTextBox.Text)
                        ? "待选择程序"
                        : (GetBoundDetectionRoiLayers(tool).Count == 0 ? "待绑定检测区" : "就绪");
                    tool.ConnectionStatus = tool.ConfigurationStatus == "就绪" ? "系统输入 · 已就绪" : "系统输入 · 待配置";
                    tool.ConnectionSummary = "系统.Image + " + GetRoiBindingSummary(tool) + " + Program";
                    break;
                default:
                    bool perRoiRequiresBinding = (tool.Kind == VmToolKind.Blob || tool.Kind == VmToolKind.GrayStat || tool.Kind == VmToolKind.EdgeMeasure) &&
                                                 VmRoiExecutionMode.Normalize(parameters.RoiExecutionMode) == VmRoiExecutionMode.PerRoi;
                    bool hasPerRoiBinding = GetBoundDetectionRoiLayers(tool).Count > 0;
                    bool hasToolImage = HasToolInputImage(tool);
                    VmToolInputBindingData imageBinding = tool.GetInputBinding("Image");
                    tool.ConfigurationStatus = !hasToolImage
                        ? "等待图像"
                        : (perRoiRequiresBinding && !hasPerRoiBinding ? "待绑定 ROI" : "就绪");
                    VmToolInputBindingData regionBinding = tool.GetInputBinding("ROI");
                    VmToolInstance regionSource = GetInputSourceTool(regionBinding);
                    object regionRaw;
                    VmRegionSnapshot regionSnapshot = regionSource != null && regionSource.TryGetOutputValue(regionBinding == null ? null : regionBinding.SourcePortName, out regionRaw)
                        ? regionRaw as VmRegionSnapshot
                        : null;
                    tool.ConnectionStatus = !hasToolImage
                        ? (imageBinding == null ? "系统输入 · 等待图像" : "Image 已连接 · 等待上游")
                        : (perRoiRequiresBinding && !hasPerRoiBinding
                            ? (imageBinding == null ? "系统输入 · 等待 ROI" : "Image 已连接 · 等待 ROI")
                            : (regionBinding == null
                                ? (imageBinding == null ? "系统输入 · 已就绪" : "Image 已连接 · 有值")
                                : (regionSnapshot == null || regionSnapshot.IsDisposed ? "Region 已连接 · 等待上游" : "Region 已连接 · 有值")));
                    tool.ConnectionSummary = tool.Kind == VmToolKind.ImageChannel || tool.Kind == VmToolKind.ImageFilter || tool.Kind == VmToolKind.ImageEnhancement || tool.Kind == VmToolKind.ImageResize || tool.Kind == VmToolKind.ImageMirror || tool.Kind == VmToolKind.ImageRotate || tool.Kind == VmToolKind.ImageAffineTransform || tool.Kind == VmToolKind.ImageProjectiveTransform || tool.Kind == VmToolKind.PolarImageUnwrap
                        ? GetImageInputSummary(tool) + " → Image"
                        : (tool.Kind == VmToolKind.ImageThreshold
                            ? GetImageInputSummary(tool) + " → Region"
                            : (tool.Kind == VmToolKind.CaliperEdgePairMeasurement
                                ? GetImageInputSummary(tool) + " → 边缘对距离/XLD"
                                : (tool.Kind == VmToolKind.LinearCaliperArrayMeasurement
                                    ? GetImageInputSummary(tool) + " → 多卡尺距离统计/XLD"
                                    : (tool.Kind == VmToolKind.CircularCaliperCircleFinder
                                        ? GetImageInputSummary(tool) + " → 圆心/半径/残差/XLD"
                                        : (tool.Kind == VmToolKind.RingWallThicknessMeasurement
                                            ? GetImageInputSummary(tool) + " → 壁厚/偏心量/XLD"
                                            : GetImageInputSummary(tool) + " + " + GetRoiInputSummary(tool))))));
                    break;
            }
            AdjustRoiConfigurationStatusS86(tool);
        }

        private void RefreshNumericJudgeEditor(VmToolInstance tool)
        {
            int judgeIndex = flowTools.IndexOf(tool);
            List<VmSourceToolOption> sourceOptions = flowTools
                .Take(Math.Max(0, judgeIndex))
                .Where(item => ToolMetadata.GetInstanceNumericOutputPorts(item).Count > 0)
                .Select(item => new VmSourceToolOption
                {
                    ToolId = item.ToolId,
                    DisplayText = item.SequenceText + "  " + item.InstanceName
                })
                .ToList();
            NumericSourceToolComboBox.ItemsSource = sourceOptions;
            NumericSourceToolComboBox.SelectedValue = tool.InputToolId;

            VmToolInstance source = GetInputSourceTool(tool);
            List<VmSourcePortOption> portOptions = source == null
                ? new List<VmSourcePortOption>()
                : ToolMetadata.GetInstanceNumericOutputPorts(source)
                    .Select(item => new VmSourcePortOption
                    {
                        PortName = item.PortName,
                        DisplayText = item.DisplayName + "  (" + item.PortName + ")",
                        DataType = item.DataType
                    })
                    .ToList();
            NumericSourcePortComboBox.ItemsSource = portOptions;
            NumericSourcePortComboBox.SelectedValue = tool.InputPortName;
            NumericOperatorComboBox.SelectedValue = tool.NumericOperator;
            NumericLowerLimitTextBox.Text = tool.NumericLowerLimit.ToString("0.###", CultureInfo.InvariantCulture);
            NumericUpperLimitTextBox.Text = tool.NumericUpperLimit.ToString("0.###", CultureInfo.InvariantCulture);
            NumericToleranceTextBox.Text = tool.NumericTolerance.ToString("0.###", CultureInfo.InvariantCulture);

            string error = GetNumericJudgeConfigurationError(tool);
            NumericConfigValidationText.Text = string.IsNullOrWhiteSpace(error)
                ? "连接有效。运行全流程时将读取上游本周期数值；独立运行使用上游最近一次结果。"
                : "配置异常：" + error;
            NumericConfigValidationText.Foreground = string.IsNullOrWhiteSpace(error)
                ? System.Windows.Media.Brushes.SeaGreen
                : System.Windows.Media.Brushes.Firebrick;
        }

        private void RefreshPortPanel(VmToolInstance tool)
        {
            inputPortRows.Clear();
            outputPortRows.Clear();

            if (tool == null)
            {
                IoToolTitleText.Text = "未选择流程工具";
                IoConnectionStatusText.Text = "请在流程区选择工具实例。";
                IoRunCurrentButton.IsEnabled = false;
                IoOpenParametersButton.IsEnabled = false;
                return;
            }

            IoToolTitleText.Text = tool.SequenceText + "  " + tool.InstanceName;
            IoConnectionStatusText.Text = tool.ConnectionStatus + " · " + tool.ConnectionSummary;
            IoRunCurrentButton.IsEnabled = tool.IsEnabled;
            IoOpenParametersButton.IsEnabled = true;

            foreach (VmPortDefinition port in ToolMetadata.GetInstanceInputPorts(tool))
            {
                inputPortRows.Add(BuildInputPortRow(tool, port));
            }

            foreach (VmPortDefinition port in ToolMetadata.GetInstanceOutputPorts(tool))
            {
                object raw;
                bool hasValue = tool.TryGetOutputValue(port.PortName, out raw);
                outputPortRows.Add(new VmPortDisplayItem
                {
                    Direction = "OUT",
                    PortName = port.PortName,
                    DisplayName = port.DisplayName,
                    DataType = port.DataType,
                    Source = tool.InstanceName + "." + port.PortName,
                    CurrentValue = hasValue ? tool.GetFormattedOutput(port.PortName) : "--",
                    Status = hasValue ? "有值" : "尚未运行",
                    IsConnected = hasValue
                });
            }
        }

        private VmPortDisplayItem BuildInputPortRow(VmToolInstance tool, VmPortDefinition port)
        {
            string source = "系统." + port.PortName;
            string currentValue = "--";
            string status = "未连接";
            bool connected = false;

            if (tool.Kind == VmToolKind.NumericJudge && port.PortName == "Value")
            {
                VmToolInstance sourceTool = GetInputSourceTool(tool);
                source = sourceTool == null
                    ? "未选择"
                    : sourceTool.InstanceName + "." + (tool.InputPortName ?? "未选择");
                double numericValue;
                connected = string.IsNullOrWhiteSpace(GetNumericJudgeConfigurationError(tool));
                if (sourceTool != null && sourceTool.TryGetNumericOutput(tool.InputPortName, out numericValue))
                {
                    currentValue = numericValue.ToString("0.###", CultureInfo.InvariantCulture);
                    status = connected ? "已连接 · 有值" : "连接异常 · 有历史值";
                }
                else
                {
                    status = connected ? "已连接 · 等待运行" : "连接异常";
                }
            }
            else if (port.PortName == "Image")
            {
                VmToolInputBindingData binding = tool.GetInputBinding("Image");
                if (binding == null)
                {
                    source = "系统.Image（当前图像）";
                    connected = currentImage != null;
                    currentValue = connected
                        ? string.Format(CultureInfo.InvariantCulture, "{0}×{1}", GetImageWidth(currentImage), GetImageHeight(currentImage))
                        : "--";
                    status = connected ? "默认输入 · 有值" : "默认输入 · 等待图像";
                }
                else
                {
                    VmToolInstance sourceTool = GetInputSourceTool(binding);
                    string bindingError = GetInputBindingConfigurationError(tool, binding);
                    VmImageSnapshot snapshot = GetImageSnapshot(sourceTool, binding.SourcePortName);
                    source = sourceTool == null ? "无效来源" : sourceTool.InstanceName + "." + binding.SourcePortName;
                    currentValue = snapshot == null ? "--" : snapshot.DisplayText;
                    connected = string.IsNullOrWhiteSpace(bindingError);
                    status = !connected
                        ? "连接异常 · " + bindingError
                        : (snapshot == null || snapshot.IsDisposed
                            ? "已连接 · 等待上游运行"
                            : (string.Equals(sourceTool.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) ? "已连接 · 有值" : "已连接 · 上游非 OK"));
                }
            }
            else if (port.PortName == "SearchROI" || port.PortName == "ROI")
            {
                VmToolInputBindingData binding = tool.GetInputBinding(port.PortName);
                if (binding != null)
                {
                    VmToolInstance sourceTool = GetInputSourceTool(binding);
                    string bindingError = GetInputBindingConfigurationError(tool, binding);
                    object raw;
                    VmRegionSnapshot snapshot = sourceTool != null && sourceTool.TryGetOutputValue(binding.SourcePortName, out raw)
                        ? raw as VmRegionSnapshot
                        : null;
                    source = sourceTool == null ? "无效来源" : sourceTool.InstanceName + "." + binding.SourcePortName;
                    currentValue = snapshot == null ? "--" : snapshot.DisplayText;
                    connected = string.IsNullOrWhiteSpace(bindingError);
                    status = !connected
                        ? "连接异常 · " + bindingError
                        : (snapshot == null || snapshot.IsDisposed
                            ? "已连接 · 等待上游运行"
                            : (string.Equals(sourceTool.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) ? "已连接 · 有值" : "已连接 · 上游非 OK"));
                }
                else
                {
                List<VmRoiLayer> boundLayers = GetBoundRoiLayers(tool);
                int detectionCount = boundLayers.Count(item => !item.IsMask);
                int maskCount = boundLayers.Count(item => item.IsMask);
                VmToolParameterData roiParameters = tool.Parameters ?? new VmToolParameterData();
                bool perRoiMode = (tool.Kind == VmToolKind.Blob || tool.Kind == VmToolKind.GrayStat || tool.Kind == VmToolKind.EdgeMeasure) &&
                                  VmRoiExecutionMode.Normalize(roiParameters.RoiExecutionMode) == VmRoiExecutionMode.PerRoi;
                connected = detectionCount > 0 || (port.IsOptional && !perRoiMode && maskCount == 0);
                source = boundLayers.Count == 0 ? "未绑定" : string.Join(" + ", boundLayers.Select(item => item.Name));
                currentValue = boundLayers.Count == 0
                    ? "--"
                    : "检测区 ×" + detectionCount.ToString(CultureInfo.InvariantCulture) + " - 屏蔽区 ×" + maskCount.ToString(CultureInfo.InvariantCulture);
                status = connected && boundLayers.Count > 0
                    ? "已连接 · " + (perRoiMode ? "逐区 " : "合并 ") + detectionCount.ToString(CultureInfo.InvariantCulture) + " 个检测区，扣除 " + maskCount.ToString(CultureInfo.InvariantCulture) + " 个屏蔽区"
                    : (maskCount > 0 && detectionCount == 0 ? "无效 · 屏蔽区缺少检测区" : (port.IsOptional && !perRoiMode ? "可选 · 全图运行" : "等待检测区绑定"));
                }
            }
            else if (port.PortName == "ShapeModel")
            {
                connected = currentTemplateItem != null && currentTemplateItem.HasModel;
                currentValue = connected ? currentTemplateItem.Name : "--";
                status = connected ? "已连接" : "等待模板";
            }
            else if (port.PortName == "Program")
            {
                connected = !string.IsNullOrWhiteSpace(HDevPathTextBox.Text);
                currentValue = connected ? Path.GetFileName(HDevPathTextBox.Text) : "--";
                status = connected ? "已连接" : "等待程序";
            }

            return new VmPortDisplayItem
            {
                Direction = "IN",
                PortName = port.PortName,
                DisplayName = port.DisplayName,
                DataType = port.DataType,
                Source = source,
                CurrentValue = currentValue,
                Status = status,
                IsConnected = connected
            };
        }

        private void NumericSourceToolComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (!inspectorUpdating && !RequireEngineeringEditS137("修改数值订阅")) { RefreshInspector(); return; }
            if (inspectorUpdating)
            {
                return;
            }

            VmToolInstance tool = FlowToolList.SelectedItem as VmToolInstance;
            if (tool == null || tool.Kind != VmToolKind.NumericJudge)
            {
                return;
            }

            tool.InputToolId = NumericSourceToolComboBox.SelectedValue as string;
            VmToolInstance source = GetInputSourceTool(tool);
            VmPortDefinition firstPort = source == null ? null : ToolMetadata.GetInstanceNumericOutputPorts(source).FirstOrDefault();
            tool.InputPortName = firstPort == null ? null : firstPort.PortName;
            RefreshUiState();
        }

        private void NumericSourcePortComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (!inspectorUpdating && !RequireEngineeringEditS137("修改数值端口")) { RefreshInspector(); return; }
            if (inspectorUpdating)
            {
                return;
            }

            VmToolInstance tool = FlowToolList.SelectedItem as VmToolInstance;
            if (tool != null && tool.Kind == VmToolKind.NumericJudge)
            {
                tool.InputPortName = NumericSourcePortComboBox.SelectedValue as string;
                RefreshUiState();
            }
        }

