        private void FlowGraphViewport_Drop(object sender, DragEventArgs e)
        {
            if (!RequireEngineeringEditS137("拖入流程工具")) return;
            if (TryHandleFlowReorderDropS77(e)) return;
            if (TryInsertDraggedFlowSnippetToGraphS71(e))
            {
                HideFlowDropHint();
