                        tool.InputSummary = BuildPointPairLineInputSummaryS70(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.TypedLineLineRelationMeasurement:
                        record = RunTypedLineLineRelationToolS71(tool);
                        tool.InputSummary = BuildTypedLineLineInputSummaryS71(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.TypedPointSetLineFittingMeasurement:
                        record = RunTypedPointSetLineFittingToolS72(tool);
                        tool.InputSummary = BuildTypedPointSetLineFitInputSummaryS72(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.TypedPointSetCircleFittingMeasurement:
                        record = RunTypedPointSetCircleFittingToolS73(tool);
                        tool.InputSummary = BuildTypedPointSetCircleFitInputSummaryS73(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.TypedPointSetEllipseFittingMeasurement:
                        record = RunTypedPointSetEllipseFittingToolS74(tool);
                        tool.InputSummary = BuildTypedPointSetEllipseFitInputSummaryS74(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.ResultLogicAggregation:
                        record = RunResultLogicAggregationTool(tool);
                        tool.InputSummary = BuildResultLogicInputSummary(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.CSharpDllScript:
                        record = RunScriptTool(tool);
                        tool.InputSummary = BuildScriptInputSummary(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.GlobalVariableRead:
                        record = RunGlobalVariableReadTool(tool);
                        tool.InputSummary = BuildGlobalVariableToolInputSummary(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    case VmToolKind.GlobalVariableWrite:
                        record = RunGlobalVariableWriteTool(tool);
                        tool.InputSummary = BuildGlobalVariableToolInputSummary(tool);
                        tool.OutputSummary = record.Message;
                        break;
                    default:
                        throw new NotSupportedException("不支持的工具类型：" + tool.Kind);
                }

                PublishToolOutputs(tool, record);
                tool.ResultCode = record.ResultCode;
                tool.RunStatus = string.Equals(record.ResultCode, "OK", StringComparison.OrdinalIgnoreCase) ? "完成" : "异常";
                if (tool.Kind == VmToolKind.OcrRecognition || tool.Kind == VmToolKind.PlanarCalibration2D || tool.Kind == VmToolKind.LineEllipseIntersectionMeasurement || tool.Kind == VmToolKind.TypedLineLineRelationMeasurement || tool.Kind == VmToolKind.TypedPointSetLineFittingMeasurement || tool.Kind == VmToolKind.TypedPointSetCircleFittingMeasurement || tool.Kind == VmToolKind.TypedPointSetEllipseFittingMeasurement)
                {
                    UpdateImageContextViewport(true);
                    ScheduleRefreshDisplay();
                }
                if (tool.Kind == VmToolKind.LocalAdaptiveThreshold || tool.Kind == VmToolKind.GrayHistogram || tool.Kind == VmToolKind.GrayLineProfile || tool.Kind == VmToolKind.BranchValueSelection)
                {
                    UpdateImageContextViewport(true);
                    ScheduleRefreshDisplay();
                }
                if (tool.Kind == VmToolKind.CameraDistortionCorrection)
                {
                    UpdateImageContextViewport(true);
                    ScheduleRefreshDisplay();
                }
                if (tool.Kind == VmToolKind.ColorInspectionHsv || tool.Kind == VmToolKind.VariationSurfaceInspection || tool.Kind == VmToolKind.NccTemplateMatch || tool.Kind == VmToolKind.PoseImageAlignment)
                { UpdateImageContextViewport(true); ScheduleRefreshDisplay(); }
                if (tool.Kind == VmToolKind.ShapeMatch || tool.Kind == VmToolKind.ImageSource || tool.Kind == VmToolKind.DataCode2DRecognition || tool.Kind == VmToolKind.BarCode1DRecognition || tool.Kind == VmToolKind.ImageChannel || tool.Kind == VmToolKind.ImageFilter || tool.Kind == VmToolKind.ImageEnhancement || tool.Kind == VmToolKind.ImageResize || tool.Kind == VmToolKind.ImageMirror || tool.Kind == VmToolKind.ImageRotate || tool.Kind == VmToolKind.ImageAffineTransform || tool.Kind == VmToolKind.ImageProjectiveTransform || tool.Kind == VmToolKind.SubpixelEdgeExtraction || tool.Kind == VmToolKind.PolarImageUnwrap || tool.Kind == VmToolKind.RoiImageExtraction || tool.Kind == VmToolKind.ImageDifference || tool.Kind == VmToolKind.DynamicThreshold || tool.Kind == VmToolKind.ImageThreshold || tool.Kind == VmToolKind.AutomaticThreshold || tool.Kind == VmToolKind.RegionMorphology || tool.Kind == VmToolKind.RegionFeatureFilter || tool.Kind == VmToolKind.RegionSetOperation || tool.Kind == VmToolKind.RegionContourMeasurement || tool.Kind == VmToolKind.XldContourFilter || tool.Kind == VmToolKind.XldAdjacentContourUnion || tool.Kind == VmToolKind.XldContourSmoothing || tool.Kind == VmToolKind.XldAffineTransform || tool.Kind == VmToolKind.XldProjectiveTransform || tool.Kind == VmToolKind.XldContourSegmentation || tool.Kind == VmToolKind.XldLineFitting || tool.Kind == VmToolKind.XldCircleFitting || tool.Kind == VmToolKind.XldEllipseFitting || tool.Kind == VmToolKind.XldRectangleFitting || tool.Kind == VmToolKind.XldLineRelationMeasurement || tool.Kind == VmToolKind.TypedPointSetLineFittingMeasurement || tool.Kind == VmToolKind.TypedPointSetCircleFittingMeasurement || tool.Kind == VmToolKind.TypedPointSetEllipseFittingMeasurement || tool.Kind == VmToolKind.PointToLineDistanceMeasurement || tool.Kind == VmToolKind.PointToCircleRadialDeviationMeasurement || tool.Kind == VmToolKind.PointToEllipseDistanceMeasurement || tool.Kind == VmToolKind.LineCircleIntersectionMeasurement || tool.Kind == VmToolKind.CircleCircleIntersectionMeasurement || tool.Kind == VmToolKind.PointPairLineConstructionMeasurement || tool.Kind == VmToolKind.CaliperEdgePairMeasurement || tool.Kind == VmToolKind.LinearCaliperArrayMeasurement || tool.Kind == VmToolKind.CircularCaliperCircleFinder || tool.Kind == VmToolKind.RingWallThicknessMeasurement)
                {
                    UpdateImageContextViewport(true);
                    ScheduleRefreshDisplay();
                }
                return record;
            }
            catch (Exception ex)
            {
                tool.ResultCode = "NG";
                tool.RunStatus = "失败";
                tool.ErrorMessage = ex.Message;
                tool.OutputSummary = "失败：" + ex.Message;
                throw;
            }
            finally
            {
                stopwatch.Stop();
                tool.ElapsedMilliseconds = stopwatch.Elapsed.TotalMilliseconds;
                if (tool.Kind == VmToolKind.ImageSource) RecordAcquisitionAttemptS115(tool);
                RefreshInspector();
                if (tool.Kind == VmToolKind.TcpClientExchange || tool.Kind == VmToolKind.ModbusTcpExchange || tool.Kind == VmToolKind.ModbusRtuExchange)
                    RefreshCommunicationTasksS120();
            }
        }

        private InspectionRecord RunNumericJudgeTool(VmToolInstance tool)
        {
            string configurationError = GetNumericJudgeConfigurationError(tool);
            if (!string.IsNullOrWhiteSpace(configurationError))
            {
                throw new InvalidOperationException(configurationError);
            }

            VmToolInstance sourceTool = GetInputSourceTool(tool);
            double value;
            if (sourceTool == null || !sourceTool.TryGetNumericOutput(tool.InputPortName, out value))
            {
                throw new InvalidOperationException("上游端口尚无有效数值。请先运行上游工具，或按顺序运行全流程。");
            }

            bool passed = EvaluateNumericJudge(tool, value);
            string operatorText = NumericJudgeOperatorOption.GetDisplayText(tool.NumericOperator);
            string limits = GetNumericJudgeLimitText(tool);
            string message = string.Format(
                CultureInfo.InvariantCulture,
                "{0}.{1}={2:0.###}，规则={3} {4}，判定={5}",
                sourceTool.InstanceName,
                tool.InputPortName,
                value,
                operatorText,
                limits,
                passed ? "OK" : "NG");

            tool.InputSummary = sourceTool.InstanceName + "." + tool.InputPortName + " = " + value.ToString("0.###", CultureInfo.InvariantCulture);
            InspectionRecord record = CreateRecord("NumericJudge", passed ? "OK" : "NG", value, message, tool);
            resultStore.Add(record);
            LogInfo("数值判定完成：" + message);
            return record;
        }

        private InspectionRecord RunTcpClientExchangeTool(VmToolInstance tool)
        {
            VmToolParameterData parameters = tool.Parameters ?? new VmToolParameterData();
            parameters.Normalize();
            string validationError = parameters.Validate(VmToolKind.TcpClientExchange);
            if (!string.IsNullOrWhiteSpace(validationError)) throw new InvalidOperationException(validationError);

            TcpFlowClientRequest requestS120 = BuildTcpRequestS120(tool, parameters);
            string payload = requestS120.Message;

            TcpFlowClientResult exchange = null;
            Dictionary<string, object> mappedResponseS117 = null;
            string resultCode = "NG";
            string errorMessage = string.Empty;
            try
            {
                object stagedS120;
                if (communicationPreparedResultsS120.TryGetValue(tool.ToolId, out stagedS120) && stagedS120 is PreparedTcpExchangeS120)
                {
                    var ready = (PreparedTcpExchangeS120)stagedS120;
                    if (ready.Error != null) throw ready.Error;
                    exchange = ready.Result;
                }
                else if (parameters.CommunicationSimulationS121)
                {
                    var ready = (PreparedTcpExchangeS120)BuildCommunicationSimulationS121(tool, parameters);
                    if (ready.Error != null) throw ready.Error;
                    exchange = ready.Result;
                }
                else exchange = TcpFlowClientService.Execute(requestS120, delegate { return isStopRequested; });
                resultCode = !parameters.TcpClientWaitForResponse || exchange.BytesReceived > 0 ? "OK" : "NG";
                if (resultCode == "NG") errorMessage = "TCP 已连接并发送，但远端关闭连接且未返回数据。";
                if (resultCode == "OK" && VmTcpResponseModeS117.Normalize(parameters.TcpResponseModeS117) != VmTcpResponseModeS117.None)
                {
                    try { mappedResponseS117 = VmTcpResponseMappingS117.Parse(exchange.ReceivedText, parameters); }
                    catch (Exception mappingError)
                    {
                        resultCode = "NG";
                        errorMessage = "响应字段映射失败：" + mappingError.Message;
                    }
                }
            }
            catch (Exception ex)
            {
                errorMessage = ex.Message;
            }

            bool connected = exchange != null && exchange.Connected;
            tool.SetOutputValue("IsSimulation", parameters.CommunicationSimulationS121);
            string sentText = exchange == null ? payload : exchange.SentText;
            string receivedText = exchange == null ? string.Empty : exchange.ReceivedText;
            double roundTrip = exchange == null ? 0 : exchange.RoundTripMilliseconds;
            double bytesSent = exchange == null ? 0 : exchange.BytesSent;
            double bytesReceived = exchange == null ? 0 : exchange.BytesReceived;
            tool.SetOutputValue("Connected", connected);
            tool.SetOutputValue("SentText", sentText);
            tool.SetOutputValue("ReceivedText", receivedText);
            tool.SetOutputValue("RoundTripMs", roundTrip);
            tool.SetOutputValue("BytesSent", bytesSent);
            tool.SetOutputValue("BytesReceived", bytesReceived);
            if (mappedResponseS117 != null)
                foreach (KeyValuePair<string, object> mapped in mappedResponseS117)
                    tool.SetOutputValue(mapped.Key, mapped.Value);
            tool.ErrorMessage = errorMessage;

            string message = string.Format(
                CultureInfo.InvariantCulture,
                (parameters.CommunicationSimulationS121 ? "离线模拟 · TCP {0}:{1} · {2}/{3} · 行尾={4} · 真实发送 0 B · 样本接收 {6} B · 解析 {7:0} ms{8}{9}" :
                    "TCP {0}:{1} · {2}/{3} · 行尾={4} · 发送 {5} B · 接收 {6} B · 往返 {7:0} ms{8}{9}"),
                parameters.TcpClientHost,
                parameters.TcpClientPort,
                VmTcpEncoding.Normalize(parameters.TcpClientEncoding),
                parameters.TcpClientWaitForResponse ? "等待响应" : "仅发送",
                VmTcpLineEnding.Normalize(parameters.TcpClientLineEnding),
                bytesSent,
                bytesReceived,
                roundTrip,
                string.IsNullOrWhiteSpace(errorMessage) ? string.Empty : " · " + errorMessage,
                BuildTcpMappedSummaryS117(mappedResponseS117));
            if (parameters.CommunicationSimulationS121) message += CommunicationSampleLabelS149(parameters);
            InspectionRecord record = CreateRecord("TcpClientExchange", resultCode, roundTrip, message, tool);
            resultStore.Add(record);
            if (resultCode == "OK") LogInfo(tool.InstanceName + " 完成：" + message);
            else AppendAlarm(tool.InstanceName + " 异常：" + message);
            return record;
        }

        private InspectionRecord RunTextAssemblyTool(VmToolInstance tool)
        {
            VmToolParameterData parameters = tool.Parameters ?? new VmToolParameterData();
            parameters.Normalize();
            string validationError = parameters.Validate(VmToolKind.TextAssembly);
            if (!string.IsNullOrWhiteSpace(validationError)) throw new InvalidOperationException(validationError);

            object rawString;
            object rawNumber;
            object rawResultCode;
            bool hasString = TryResolveOptionalToolInputValue(tool, "String", out rawString);
            bool hasNumber = TryResolveOptionalToolInputValue(tool, "Number", out rawNumber);
            bool hasResultCode = TryResolveOptionalToolInputValue(tool, "ResultCode", out rawResultCode);
            string stringValue = hasString ? Convert.ToString(rawString, CultureInfo.InvariantCulture) ?? string.Empty : string.Empty;
            string resultCodeValue = hasResultCode ? Convert.ToString(rawResultCode, CultureInfo.InvariantCulture) ?? string.Empty : string.Empty;
            string numberValue = string.Empty;
            if (hasNumber)
            {
                double number;
                try
                {
                    number = Convert.ToDouble(rawNumber, CultureInfo.InvariantCulture);
                }
                catch (Exception ex)
                {
                    throw new InvalidOperationException("Number 输入无法转换为数值：" + ex.Message, ex);
                }
                numberValue = number.ToString(parameters.TextAssemblyNumberFormat, CultureInfo.InvariantCulture);
            }

            string policy = VmTextAssemblyEmptyPolicy.Normalize(parameters.TextAssemblyEmptyPolicy);
            List<KeyValuePair<string, string>> subscribedValues = new List<KeyValuePair<string, string>>();
            if (hasString) subscribedValues.Add(new KeyValuePair<string, string>("String", stringValue));
            if (hasNumber) subscribedValues.Add(new KeyValuePair<string, string>("Number", numberValue));
            if (hasResultCode) subscribedValues.Add(new KeyValuePair<string, string>("ResultCode", resultCodeValue));
            KeyValuePair<string, string> empty = subscribedValues.FirstOrDefault(item => string.IsNullOrEmpty(item.Value));
            if (policy == VmTextAssemblyEmptyPolicy.Reject && !string.IsNullOrEmpty(empty.Key))
                throw new InvalidOperationException(empty.Key + " 已订阅但值为空，当前空值策略为“拒绝”。");

            string separator = DecodeTextAssemblySeparator(parameters.TextAssemblySeparator);
            IEnumerable<string> valueSequence = subscribedValues.Select(item => item.Value);
            if (policy == VmTextAssemblyEmptyPolicy.Skip) valueSequence = valueSequence.Where(item => !string.IsNullOrEmpty(item));
            string valuesText = string.Join(separator, valueSequence);
            string text = (parameters.TextAssemblyTemplate ?? string.Empty)
                .Replace("{Values}", valuesText)
                .Replace("{String}", stringValue)
                .Replace("{Number}", numberValue)
                .Replace("{ResultCode}", resultCodeValue)
                .Replace("{Separator}", separator);

            tool.SetOutputValue("Text", text);
            tool.SetOutputValue("Length", (double)text.Length);
            string preview = text.Replace("\r", "\\r").Replace("\n", "\\n").Replace("\t", "\\t");
            if (preview.Length > 120) preview = preview.Substring(0, 117) + "...";
            string message = string.Format(
                CultureInfo.InvariantCulture,
                "文本组装完成 · 输入 {0} 项 · 空值策略={1} · 长度={2} · Text={3}",
                subscribedValues.Count,
                policy,
                text.Length,
                preview);
            InspectionRecord record = CreateRecord("TextAssembly", "OK", text.Length, message, tool);
            resultStore.Add(record);
            LogInfo(tool.InstanceName + " 完成：" + message);
            return record;
        }

        private InspectionRecord RunTextParserTool(VmToolInstance tool)
        {
            VmToolParameterData parameters = tool.Parameters ?? new VmToolParameterData();
            parameters.Normalize();
            string validationError = parameters.Validate(VmToolKind.TextParser);
            if (!string.IsNullOrWhiteSpace(validationError)) throw new InvalidOperationException(validationError);

            object rawInput;
            if (!TryResolveOptionalToolInputValue(tool, "String", out rawInput))
                throw new InvalidOperationException("文本解析必须连接 String 输入。");
            string input = Convert.ToString(rawInput, CultureInfo.InvariantCulture) ?? string.Empty;
            List<string> fields;
            string mode = VmTextParserMode.Normalize(parameters.TextParserMode);
            try
            {
                if (mode == VmTextParserMode.Regex)
                {
                    Regex regex = new Regex(parameters.TextParserPattern, RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(200));
                    fields = regex.Matches(input).Cast<Match>()
                        .Select(match => match.Groups.Count > 1 && match.Groups[1].Success ? match.Groups[1].Value : match.Value)
                        .ToList();
                }
                else
                {
                    string separator = DecodeTextAssemblySeparator(parameters.TextParserPattern);
                    if (separator.Length == 0) throw new InvalidOperationException("文本解析后的字面分隔符不能为空。");
                    fields = input.Split(new[] { separator }, StringSplitOptions.None).ToList();
                }
            }
            catch (RegexMatchTimeoutException ex)
            {
                throw new InvalidOperationException("文本解析正则匹配超过 200 ms 安全时限。", ex);
            }

            if (parameters.TextParserTrim) fields = fields.Select(item => (item ?? string.Empty).Trim()).ToList();
            string emptyPolicy = VmTextAssemblyEmptyPolicy.Normalize(parameters.TextParserEmptyPolicy);
            string errorMessage = string.Empty;
            if (emptyPolicy == VmTextAssemblyEmptyPolicy.Reject && fields.Any(string.IsNullOrEmpty))
                errorMessage = "解析结果包含空字段，当前空字段策略为“拒绝”。";
            if (emptyPolicy == VmTextAssemblyEmptyPolicy.Skip) fields = fields.Where(item => !string.IsNullOrEmpty(item)).ToList();

            int selectedIndex = parameters.TextParserFieldIndex - 1;
            bool matched = string.IsNullOrWhiteSpace(errorMessage) && selectedIndex >= 0 && selectedIndex < fields.Count;
            string selectedText = matched ? fields[selectedIndex] : string.Empty;
            if (string.IsNullOrWhiteSpace(errorMessage) && !matched)
                errorMessage = fields.Count == 0 ? "文本解析没有得到任何匹配字段。" : "字段序号超出解析结果范围。";

            double numericValue = 0;
            bool numericReady = false;
            if (matched && parameters.TextParserConvertNumber)
            {
                numericReady = double.TryParse(selectedText, NumberStyles.Float, CultureInfo.InvariantCulture, out numericValue) &&
                               !double.IsNaN(numericValue) && !double.IsInfinity(numericValue);
                if (!numericReady) errorMessage = "所选字段无法按 InvariantCulture 转换为有限数值。";
            }

            string resultCode = string.IsNullOrWhiteSpace(errorMessage) ? "OK" : "NG";
            tool.SetOutputValue("Text", selectedText);
            tool.SetOutputValue("Number", parameters.TextParserConvertNumber && numericReady ? (object)numericValue : null);
            tool.SetOutputValue("FieldCount", (double)fields.Count);
            tool.SetOutputValue("Matched", matched);
            tool.ErrorMessage = errorMessage;

            string preview = selectedText.Replace("\r", "\\r").Replace("\n", "\\n").Replace("\t", "\\t");
            if (preview.Length > 100) preview = preview.Substring(0, 97) + "...";
            string message = string.Format(
                CultureInfo.InvariantCulture,
                "文本解析 {0} · 模式={1} · 字段={2}/{3} · Text={4}{5}{6}",
                resultCode,
                mode,
                parameters.TextParserFieldIndex,
                fields.Count,
                preview,
                numericReady ? " · Number=" + numericValue.ToString("0.############", CultureInfo.InvariantCulture) : string.Empty,
                string.IsNullOrWhiteSpace(errorMessage) ? string.Empty : " · " + errorMessage);
            InspectionRecord record = CreateRecord("TextParser", resultCode, numericReady ? numericValue : fields.Count, message, tool);
            resultStore.Add(record);
            if (resultCode == "OK") LogInfo(tool.InstanceName + " 完成：" + message);
            else AppendAlarm(tool.InstanceName + " 异常：" + message);
            return record;
        }

        private InspectionRecord RunNumericCalculationTool(VmToolInstance tool)
        {
            VmToolParameterData parameters = tool.Parameters ?? new VmToolParameterData();
            parameters.Normalize();
            string validationError = parameters.Validate(VmToolKind.NumericCalculation);
            if (!string.IsNullOrWhiteSpace(validationError)) throw new InvalidOperationException(validationError);

            double numberA = ResolveFiniteNumericCalculationInput(tool, "NumberA", true);
            string operation = VmNumericCalculationOperation.Normalize(parameters.NumericCalculationOperation);
            bool requiresNumberB = VmNumericCalculationOperation.RequiresSecondOperand(operation);
            double numberB = requiresNumberB ? ResolveFiniteNumericCalculationInput(tool, "NumberB", true) : 0;
            double result;
            switch (operation)
            {
                case VmNumericCalculationOperation.Subtract:
                    result = numberA - numberB;
                    break;
                case VmNumericCalculationOperation.Multiply:
                    result = numberA * numberB;
                    break;
                case VmNumericCalculationOperation.Divide:
                    if (numberB == 0) throw new InvalidOperationException("数值运算除数 NumberB 不能为零。");
                    result = numberA / numberB;
                    break;
                case VmNumericCalculationOperation.Minimum:
                    result = Math.Min(numberA, numberB);
                    break;
                case VmNumericCalculationOperation.Maximum:
                    result = Math.Max(numberA, numberB);
                    break;
                case VmNumericCalculationOperation.Absolute:
                    result = Math.Abs(numberA);
                    break;
                case VmNumericCalculationOperation.Round:
                    result = Math.Round(numberA, parameters.NumericCalculationRoundDigits, MidpointRounding.AwayFromZero);
                    break;
                default:
                    result = numberA + numberB;
                    break;
            }

            if (double.IsNaN(result) || double.IsInfinity(result))
                throw new InvalidOperationException("数值运算结果不是有限数值，请检查输入范围和运算类型。");

            double operandCount = requiresNumberB ? 2 : 1;
            tool.SetOutputValue("Number", result);
            tool.SetOutputValue("OperandCount", operandCount);
            tool.SetOutputValue("Operation", operation);
            tool.SetOutputValue("ResultCode", "OK");
            string message = string.Format(
                CultureInfo.InvariantCulture,
                "数值运算完成 · Operation={0} · A={1:0.############}{2} · Number={3:0.############}",
                operation,
                numberA,
                requiresNumberB ? " · B=" + numberB.ToString("0.############", CultureInfo.InvariantCulture) : string.Empty,
                result);
            InspectionRecord record = CreateRecord("NumericCalculation", "OK", result, message, tool);
            resultStore.Add(record);
            LogInfo(tool.InstanceName + " 完成：" + message);
            return record;
        }

        private InspectionRecord RunResultLogicAggregationTool(VmToolInstance tool)
        {
            VmToolParameterData parameters = tool.Parameters ?? new VmToolParameterData();
            parameters.Normalize();
            string validationError = parameters.Validate(VmToolKind.ResultLogicAggregation);
            if (!string.IsNullOrWhiteSpace(validationError)) throw new InvalidOperationException(validationError);

            string operation = VmResultLogicOperation.Normalize(parameters.ResultLogicOperation);
            bool requiresB = VmResultLogicOperation.RequiresSecondInput(operation);
            bool stateA = ResolveResultLogicInputState(tool, "ResultCodeA", parameters);
            bool stateB = requiresB && ResolveResultLogicInputState(tool, "ResultCodeB", parameters);
            bool isOk;
            switch (operation)
            {
                case VmResultLogicOperation.AnyOk:
                    isOk = stateA || stateB;
                    break;
                case VmResultLogicOperation.Not:
                    isOk = !stateA;
                    break;
                case VmResultLogicOperation.PassThrough:
                    isOk = stateA;
                    break;
                default:
                    isOk = stateA && stateB;
                    break;
            }

            double inputCount = requiresB ? 2 : 1;
            double passedCount = (stateA ? 1 : 0) + (requiresB && stateB ? 1 : 0);
            string resultCode = isOk ? "OK" : "NG";
            tool.SetOutputValue("ResultCode", resultCode);
            tool.SetOutputValue("IsOk", isOk);
            tool.SetOutputValue("InputCount", inputCount);
            tool.SetOutputValue("PassedCount", passedCount);
            string message = string.Format(
                CultureInfo.InvariantCulture,
                "结果逻辑汇总完成 · Operation={0} · InputCount={1:0} · PassedCount={2:0} · ResultCode={3}",
                operation,
                inputCount,
                passedCount,
                resultCode);
            InspectionRecord record = CreateRecord("ResultLogicAggregation", resultCode, passedCount, message, tool);
            resultStore.Add(record);
            if (isOk) LogInfo(tool.InstanceName + " 完成：" + message);
            else AppendAlarm(tool.InstanceName + " 判定 NG：" + message);
            return record;
        }

        private InspectionRecord RunScriptTool(VmToolInstance tool)
        {
            VmToolParameterData parameters = tool.Parameters ?? new VmToolParameterData();
            parameters.Normalize();
            string validationError = parameters.Validate(VmToolKind.CSharpDllScript);
            if (!string.IsNullOrWhiteSpace(validationError)) throw new InvalidOperationException(validationError);
            if (VmScriptExecutionMode.Normalize(parameters.ScriptExecutionMode) == VmScriptExecutionMode.Dll &&
                !string.IsNullOrWhiteSpace(parameters.ScriptResourceId))
            {
                // Report missing or damaged managed resources before resolving optional
                // upstream values so the operator sees the actionable root cause first.
                externalResourceService.EnsureReadyForExecution(GetExternalResourceById(parameters.ScriptResourceId));
            }

            ScriptToolContext context = new ScriptToolContext
            {
                ParameterNumber = parameters.ScriptParameterNumber,
                ParameterText = parameters.ScriptParameterText ?? string.Empty
            };
            object raw;
            if (TryResolveOptionalToolInputValue(tool, "NumberA", out raw))
            {
                context.NumberA = ConvertScriptNumber(raw, "NumberA");
                context.HasNumberA = true;
            }
            if (TryResolveOptionalToolInputValue(tool, "NumberB", out raw))
            {
                context.NumberB = ConvertScriptNumber(raw, "NumberB");
                context.HasNumberB = true;
            }
            if (TryResolveOptionalToolInputValue(tool, "String", out raw))
            {
                context.Text = Convert.ToString(raw, CultureInfo.InvariantCulture) ?? string.Empty;
                context.HasText = true;
            }
            if (TryResolveOptionalToolInputValue(tool, "ResultCode", out raw))
            {
                context.ResultCode = Convert.ToString(raw, CultureInfo.InvariantCulture) ?? string.Empty;
                context.HasResultCode = true;
            }
            PopulateScriptNamedContext(tool, parameters, context);

            ScriptToolExecutionReport report;
            try
            {
                report = scriptToolService.Execute(CreateScriptExecutionRequest(parameters, context));
            }
            catch (Exception ex)
            {
                tool.SetOutputValue("Number", null);
                tool.SetOutputValue("Text", string.Empty);
                tool.SetOutputValue("ResultCode", "NG");
                tool.SetOutputValue("IsOk", false);
                tool.SetOutputValue("AssemblyVersion", string.Empty);
                tool.SetOutputValue("AssemblySha256", string.Empty);
                tool.SetOutputValue("Diagnostics", ex.Message);
                tool.SetOutputValue("ExecutionMs", 0d);
                throw;
            }

            ScriptToolResult result = report.Result;
            try { ApplyScriptNamedOutputs(tool, parameters, result); }
            catch (Exception ex)
            {
                tool.ClearRuntimeOutputs();
                tool.SetOutputValue("Diagnostics", ex.Message);
                tool.SetOutputValue("ResultCode", "NG");
                tool.SetOutputValue("IsOk", false);
                throw;
            }
            tool.SetOutputValue("Number", result.HasNumber ? (object)result.Number : null);
            tool.SetOutputValue("Text", result.Text ?? string.Empty);
            tool.SetOutputValue("ResultCode", result.ResultCode);
            tool.SetOutputValue("IsOk", result.IsOk);
            tool.SetOutputValue("AssemblyVersion", report.AssemblyVersion ?? string.Empty);
            tool.SetOutputValue("AssemblySha256", report.AssemblySha256 ?? string.Empty);
            tool.SetOutputValue("Diagnostics", report.Diagnostics ?? string.Empty);
            tool.SetOutputValue("ExecutionMs", report.ElapsedMilliseconds);
            string numberText = result.HasNumber ? result.Number.ToString("0.############", CultureInfo.InvariantCulture) : "--";
            string message = string.Format(
                CultureInfo.InvariantCulture,
                "脚本 {0} · Number={1} · Text={2} · {3} · {4:0.###} ms · {5}",
                result.ResultCode,
                numberText,
                ShortenScriptText(result.Text),
                BuildScriptNamedOutputSummary(parameters, result),
                report.ElapsedMilliseconds,
                report.Diagnostics);
            InspectionRecord record = CreateRecord("CSharpDllScript", result.ResultCode, result.HasNumber ? result.Number : 0, message, tool);
            resultStore.Add(record);
            if (result.IsOk) LogInfo(tool.InstanceName + " 完成：" + message);
            else AppendAlarm(tool.InstanceName + " 返回 NG：" + message);
            return record;
        }

        private static double ConvertScriptNumber(object value, string portName)
        {
            double number;
            try { number = Convert.ToDouble(value, CultureInfo.InvariantCulture); }
            catch (Exception ex) { throw new InvalidOperationException("脚本输入 " + portName + " 不能转换为数值：" + ex.Message, ex); }
            if (double.IsNaN(number) || double.IsInfinity(number))
                throw new InvalidOperationException("脚本输入 " + portName + " 必须是有限数值。");
            return number;
        }

        private static string ShortenScriptText(string value)
        {
            string text = (value ?? string.Empty).Replace("\r", " ").Replace("\n", " ");
            return text.Length <= 80 ? text : text.Substring(0, 77) + "...";
        }

        private string BuildScriptInputSummary(VmToolInstance tool)
        {
            List<string> items = new List<string>();
            foreach (string portName in new[] { "NumberA", "NumberB", "String", "ResultCode" })
            {
                VmToolInputBindingData binding = tool == null ? null : tool.GetInputBinding(portName);
                VmToolInstance source = GetInputSourceTool(binding);
                if (binding != null && source != null) items.Add(portName + "←" + source.InstanceName + "." + binding.SourcePortName);
            }
            if (tool != null && tool.Parameters != null)
            {
                tool.Parameters.Normalize();
                foreach (VmScriptInterfaceMemberData member in tool.Parameters.ScriptInterfaceMembers.Where(item => item.Direction == VmScriptMemberDirection.Input))
                {
                    VmToolInputBindingData binding = tool.GetInputBinding(member.PortName);
                    VmToolInstance source = GetInputSourceTool(binding);
                    if (binding != null && source != null) items.Add(member.Name + "←" + source.InstanceName + "." + binding.SourcePortName);
                    else if (!string.IsNullOrEmpty(member.DefaultValue)) items.Add(member.Name + "=默认");
                    else if (member.IsRequired) items.Add(member.Name + "=缺失");
                }
                int parameterCount = tool.Parameters.ScriptInterfaceMembers.Count(item => item.Direction == VmScriptMemberDirection.Parameter);
                if (parameterCount > 0) items.Add("命名参数×" + parameterCount.ToString(CultureInfo.InvariantCulture));
            }
            return items.Count == 0 ? "受控参数（无订阅）" : string.Join(" + ", items);
        }

        private bool ResolveResultLogicInputState(VmToolInstance tool, string portName, VmToolParameterData parameters)
        {
            object rawValue;
            if (!TryResolveOptionalToolInputValue(tool, portName, out rawValue) || rawValue == null)
                throw new InvalidOperationException("结果逻辑汇总必须连接 " + portName + " 输入，且上游必须已输出结果码。");

            string value = Convert.ToString(rawValue, CultureInfo.InvariantCulture) ?? string.Empty;
            if (parameters.ResultLogicTrimInput) value = value.Trim();
            if (value.Length == 0)
                throw new InvalidOperationException("结果逻辑汇总 " + portName + " 不能为空；仅允许 OK 或 NG。");

            StringComparison comparison = parameters.ResultLogicCaseSensitive ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
            if (string.Equals(value, "OK", comparison)) return true;
            if (string.Equals(value, "NG", comparison)) return false;
            throw new InvalidOperationException("结果逻辑汇总 " + portName + " 的值“" + value + "”无效；仅允许 OK 或 NG。" +
                                                (parameters.ResultLogicCaseSensitive ? "当前严格区分大小写。" : "当前不区分大小写。"));
        }

        private double ResolveFiniteNumericCalculationInput(VmToolInstance tool, string portName, bool required)
        {
            object rawValue;
            if (!TryResolveOptionalToolInputValue(tool, portName, out rawValue))
            {
                if (required) throw new InvalidOperationException("数值运算必须连接 " + portName + " 输入。");
                return 0;
            }

            double value;
            try
            {
                value = Convert.ToDouble(rawValue, CultureInfo.InvariantCulture);
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException(portName + " 输入无法转换为数值：" + ex.Message, ex);
            }
            if (double.IsNaN(value) || double.IsInfinity(value))
                throw new InvalidOperationException(portName + " 输入必须是有限数值，不能为 NaN 或 Infinity。");
            return value;
        }

        private bool TryResolveOptionalToolInputValue(VmToolInstance tool, string portName, out object value)
        {
            value = null;
            VmToolInputBindingData binding = tool.GetInputBinding(portName);
            if (binding == null) return false;
            VmToolInstance source = GetInputSourceTool(binding);
            if (source == null) throw new InvalidOperationException(portName + " 输入来源不存在。");
            if (!source.TryGetOutputValue(binding.SourcePortName, out value) || value == null)
                throw new InvalidOperationException(source.InstanceName + "." + binding.SourcePortName + " 尚无有效值，请先运行上游工具。");
            return true;
        }

        private static string DecodeTextAssemblySeparator(string value)
        {
            string source = value ?? string.Empty;
            StringBuilder builder = new StringBuilder(source.Length);
            for (int index = 0; index < source.Length; index++)
            {
                char current = source[index];
                if (current != '\\' || index + 1 >= source.Length)
                {
                    builder.Append(current);
                    continue;
                }
                char escaped = source[++index];
                if (escaped == 'r') builder.Append('\r');
                else if (escaped == 'n') builder.Append('\n');
                else if (escaped == 't') builder.Append('\t');
                else if (escaped == '\\') builder.Append('\\');
                else
                {
                    builder.Append('\\');
                    builder.Append(escaped);
                }
            }
            return builder.ToString();
        }

        private string ResolveOptionalToolInputText(VmToolInstance tool, string portName)
        {
            VmToolInputBindingData binding = tool.GetInputBinding(portName);
            if (binding == null) return string.Empty;
            VmToolInstance source = GetInputSourceTool(binding);
            if (source == null) throw new InvalidOperationException(portName + " 输入来源不存在。");
            object value;
            if (!source.TryGetOutputValue(binding.SourcePortName, out value) || value == null)
                throw new InvalidOperationException(source.InstanceName + "." + binding.SourcePortName + " 尚无有效值，请先运行上游工具。");
            if (value is double) return ((double)value).ToString("0.############", CultureInfo.InvariantCulture);
            if (value is float) return ((float)value).ToString("0.############", CultureInfo.InvariantCulture);
            return Convert.ToString(value, CultureInfo.InvariantCulture) ?? string.Empty;
        }

